INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Action fit', '✓', 'Physical construction as territorial assertion is core to New Meridian. The covert element is unannounced intent — the visible act is public. All five factions acknowledge building as a valid form of presence.', 'Art 00 §7 — faction doctrines', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Voice fit', '✓', 'All five perspectives are doctrinally distinct. Guild\'s \"permanence is possible here\" is the foundational argument; Syndicate\'s \"the question is who captures it\" reframes construction as economic extraction; Ghost\'s \"commitments are data points\" is cold and analytical. No faction sounds like another.', 'Art 00 §7 — faction profiles', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Doctrine alignment', '✓', 'Building directly serves Guild doctrine (permanence, structural investment). Captured via portrait submitter=+1 and cost affinity. No opponent target → doctrine_mod N/A.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Card type fit', '✓', 'Standard: every faction must establish structure; no faction-specific exclusivity warranted. CovertOperation: unannounced intent is the covert element, not the visible act. Fills the universal territorial foundation role — no standard card duplicates it.', 'Art 04 §6.2; Art 04b §5', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Taxonomy fit', '✓', 'Territory / Add / StructureBlock — unambiguous. Layer is Territory because the target is a StructureBlock, not because of the Add verb.', 'Art 04b §4', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Balance', '✓', 'Automatic resolution gated by dual cost + presence prerequisite + no-existing-structure restriction. Not independently playable without prior presence. Guild affinity waives district native only — cost-scoped, not difficulty.', 'Art 02 §6–§7', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Effect duration', '✓', 'No duration — structure placement is permanent; persists until removed.', '—', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Persistence', '✓', 'Immediate — card fully resolved at resolution beat; no lingering game-state marker', 'Art 04 §6', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Trigger validity', '✓', '`trigger = None`', '—', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Portrait validity', '✓', 'Guild `submitter=+1`: permanence doctrine — core alignment (DIR.PA.1, SYN.PA.2). Ghost `submitter=−1`: structure is a permanent visible commitment; Ghost doctrine is concealment, not construction (DIR.PA.1, SYN.PA.2). Directorate: no entry — builds pragmatically (\"if it serves the mandate\"); instrumental, not doctrinal. Network: no entry — presence-building via community relationships (STD.CA.3), not structures; observational stance confirms absence. Syndicate: no entry — doctrine is acquisition and capital flow; \"who captures it\" is observer framing, not builder framing. No direct Portrait track shift in effect fields (DIR.PA.2). All entries submitter-bounded (SYN.PA.2).', 'Art 04 §6.2', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Supported by zones', '✓', '`target_district = district.any` — valid. Ring entry implicit via presence requirement in restriction.', 'Art 01 §6–§7', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Supported by components', '✓', 'StructureBlock (Art 02 §6); presence token / deployment marker in restriction (Art 02 §6); faction native + district native cost (Art 02 §7).', 'Art 02 §6–§7', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Supported by game procedure', '✓', 'Submitted in Dispatch (Art 03 §9.1); Beat 3 Resolution Grid (Art 03 §9.4). ARBITER places Structure Block at Beat 3 outcome. Guild affinity evaluated at dispatch.', 'Art 03 §9, §9.4', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Data schema validation', '⚠', '04-n70 (cited here) closed S95, stale reference — re-verified S154 via `audit_card_corpus.py` against current §6.1/§6.2: missing explicit declarations for `persistence_clearing_trigger`, `boost`, `on_accept`, `on_decline`, `on_discard`, `ps_framing`, `design_note`, `arbiter_note` (schema growth post-S95, mostly `=None`-eligible — same corpus-wide Phase 0 D2 gap as most CA/PA cards, not unique to this card).', 'Art 04 §6.1–§6.3', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Card narrative', '⚠', 'Card Story block confirmed still empty (04-n79 genuinely open, not stale)', 'Art 04 §5 P26', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Outcome determinacy', '✓', '`Automatic`, single deterministic outcome (`success` only; `successcrit`/`fail`/`failcrit` all `None`).', 'Art 04 §5 P27', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.1', 'Resource cost positioning', '✓', 'Dual-resource cost (faction native + district native), cross-faction-resource tier. `cost`\'s first term typed to `.native`; second term corrected from bare `resource.district(native)` (misusing \"native\" as the district-reference argument) to `district.target.native` (schema_cleanup_log #22, closed S148). Tier match conditional on the still-open whole-set economic model decision (04-n178) — not a defect of this card specifically.', 'Art 00a §9.2', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Action fit', '✓', 'Demolition as covert territorial disruption is grounded — the act is visible, the source is not. The asymmetry with STD.CA.1 (probabilistic vs. Automatic) correctly reflects operating against someone else\'s infrastructure rather than your own.', 'Art 00 §7 — faction doctrines', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Voice fit', '✓', 'Guild\'s \"something has gone badly wrong\" and Network\'s \"infrastructure of control needs to come down\" are the sharpest contrast in the set. Ghost\'s absence-as-data read is clean. All five doctrinally distinct.', 'Art 00 §7 — faction profiles', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Doctrine alignment', '✓', '`target_faction = faction.opponent` is set; `doctrine_mod = None` is an explicit design choice — demolition difficulty reflects physical opportunity (ring, restriction), not doctrinal relationship.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Card type fit', '✓', 'Standard: all factions engage in demolition as territorial disruption. CovertOperation: source undisclosed. Distinct from STD.CA.1 — Remove vs. Add, probabilistic vs. Automatic.', 'Art 04 §6.2; Art 04b §5', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Taxonomy fit', '✓', 'Territory / Remove / StructureBlock. Layer is Territory because the target is a StructureBlock.', 'Art 04b §4', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Balance', '✓', 'Same dual cost as STD.CA.1, probabilistic at threshold 50. Ring_mod {0:−15, 1:−10, 2:0, 3:+10} — harder near Chorus Node. Crit success salvage rewards execution; crit fail PS loss is a meaningful downside.', 'Art 02 §6–§7', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Effect duration', '✓', 'No duration — structure removal is permanent; persists until rebuilt.', '—', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Persistence', '✓', 'Immediate — card fully resolved at resolution beat; no lingering game-state marker', 'Art 04 §6', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Trigger validity', '✓', '`trigger = None`', '—', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Portrait validity', '✓', 'Guild `submitter=−1`: demolition against permanence doctrine — \"we do not unmake\" (DIR.PA.1, SYN.PA.2). Network `submitter=+1`: counter-entrenchment doctrine — removing infrastructure of control is on-doctrine (DIR.PA.1, SYN.PA.2). Directorate `submitter=−1`: structures represent institutional investment; doctrinal reluctance parallels STD.CA.4 (DIR.PA.1, SYN.PA.2). Ghost: no entry — analytical observer, not demolition-as-doctrine; absence justified. Syndicate: no entry — pragmatic asset-management framing, no doctrinal signal; absence justified. `failcrit standing -= 1` is Public Standing (Art 02), not Portrait — DIR.PA.2 clear.', 'Art 04 §6.2; Art 02 §11', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Supported by zones', '✓', '`target_district = district.any`. Restriction uses self-or-adjacent presence — adjacency model required; district_adjacency confirmed (DB-09).', 'Art 01 §6–§7', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Supported by components', '✓', 'StructureBlock target (Art 02 §6); presence in restriction (Art 02 §6); dual cost (§8); failcrit `standing -= 1` (Art 02 §11).', 'Art 02 §6–§8; Art 02 §11', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Supported by game procedure', '✓', 'Dispatch (Art 03 §9.1); Beat 3 Resolution Grid (Art 03 §9.4.2); d100 threshold 50 with ring_mod. ARBITER removes Structure Block on success; standing loss on crit fail — Beat 3 outcome steps.', 'Art 03 §9, §11', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Data schema validation', '⚠', '04-n70 (cited here) closed S95, stale reference — re-verified S154 via `audit_card_corpus.py` against current §6.1/§6.2: missing explicit declarations for `persistence_clearing_trigger`, `boost`, `on_accept`, `on_decline`, `on_discard`, `ps_framing`, `design_note`, `arbiter_note` (schema growth post-S95, mostly `=None`-eligible — same corpus-wide Phase 0 D2 gap, not unique to this card).', 'Art 04 §6.1–§6.3', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Card narrative', '⚠', 'Card Story block confirmed still empty (04-n79 genuinely open, not stale)', 'Art 04 §5 P26', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Outcome determinacy', '✓', '`d100`; success/successcrit/failcrit populated (fail=None), no `game.choose_one()` or conditional branching in any tier — each resolves deterministically.', 'Art 04 §5 P27', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.2', 'Resource cost positioning', '✓', 'Dual-resource cost (faction native + district native), cross-faction-resource tier. `cost`\'s first term typed to `.native`; second term corrected from bare `resource.district(native)` (misusing \"native\" as the district-reference argument) to `district.target.native` (schema_cleanup_log #22, closed S148). Tier/power match otherwise unexamined.', 'Art 00a §9.2', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Action fit', '✓', 'Presence-deepening in a district you already occupy is grounded. Campaign is relational/operational deepening of an existing footprint — distinct from entry.', 'Art 00 §7 — faction doctrines', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Voice fit', '✓', 'Ghost\'s \"presence creates exposure\" explains why Ghost doesn\'t over-extend; Network\'s \"relationships are how things actually change\" directly justifies the affinity. All five doctrinally distinct.', 'Art 00 §7 — faction profiles', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Doctrine alignment', '✓', 'Presence-deepening through community relationships directly serves Network doctrine (relational growth). Captured via portrait submitter=+1 and cost affinity. No opponent target → doctrine_mod N/A.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Card type fit', '✓', 'Standard: all factions build presence. CovertOperation: presence-building is done quietly. Structurally mirrors STD.CA.1 (presence vs. structure) — distinct role, not duplicative.', 'Art 04 §6.2; Art 04b §5', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Taxonomy fit', '✓', 'Territory / Add / PresenceToken. Layer is Territory because the target is a PresenceToken.', 'Art 04b §4', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Balance', '✓', 'Automatic gated by presence prerequisite — same structure as STD.CA.1. Network affinity waives district native (relational, not material). Intentional cost symmetry with STD.CA.1.', 'Art 02 §6–§7', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Effect duration', '✓', 'No duration — presence placement is permanent until removed.', '—', '04___Card_System___Part2_Standard.md');
