INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Trigger validity', '✓', '`trigger = None`', '—', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Portrait validity', '✓', 'Network `submitter=+1`: relational growth is doctrinally core (DIR.PA.1, SYN.PA.2). Guild: no entry — STD.CA.1/structural investment is Guild\'s primary presence signal; Campaign is available but not doctrinally distinct; absence justified. Directorate: no entry — presence-building is instrumental (\"where the mandate requires it\"), not doctrinal; absence justified. Ghost: no entry — \"presence creates exposure\" frames expansion as calculated exception, not doctrinal endorsement; absence justified. Syndicate: no entry — community presence-building is not Syndicate\'s mode; capital and acquisition is; absence justified. No direct Portrait track shift in effect fields (DIR.PA.2).', 'Art 04 §6.2', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Supported by zones', '✓', '`target_district = district.any`. Ring entry implicit via presence restriction.', 'Art 01 §6–§7', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Supported by components', '✓', 'PresenceToken (Art 02 §6); faction native + district native cost (Art 02 §7).', 'Art 02 §6, §7', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.CA.3', 'Supported by game procedure', '✓', 'Dispatch (Art 03 §9.1); Beat 3 Resolution Grid (Art 03 §9.4). ARBITER places PresenceToken on success. Network affinity evaluated at dispatch.', 'Art 03 §9, §9.4', '04___Card_System___Part2_Standard.md');
