INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.PA.6', 'Action fit', '✓', 'Economic sanctions are a legitimate public instrument — all factions can apply financial pressure', 'Art 00 §7', '04___Card_System___Part2_Standard.md');
