INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.PA.6', 'Doctrine alignment', '✓', 'Syndicate +15 threshold + portrait +1: Capital leverage doctrine aligns with economic pressure. Guild portrait −1: economic weapons conflict with permanence-through-building doctrine. doctrine_mod accounts for target relationship', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part2_Standard.md');
