INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.PA.9', 'Action fit', '✓', 'Minor, universal grassroots outreach — deliberately the low-floor action guaranteeing at least one legal, meaningful move every Beat 4', 'Art 00a §4.8c', '04___Card_System___Part2_Standard.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.PA.9', 'Voice fit', '✓', 'All five perspectives distinct and doctrinally grounded: Guild\'s show-the-work framing, Directorate\'s institutional-continuity framing, Network\'s outreach-is-the-mission framing, Ghost\'s reluctant-but-necessary framing, Syndicate\'s cheap-relevance framing', 'Art 00 §7', '04___Card_System___Part2_Standard.md');
