INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.PA.9', 'Persistence', '✓', 'Immediate + `on_discard` set (P29) — the only card in the corpus using `on_discard`; behavior is fully defined at schema level (Art 04 §6, P29), not restated per-card', 'Art 04 §6', '04___Card_System___Part2_Standard.md');
