INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Balance', '✓', '`cost = None` — reward from STD.CA.9 success (2 Capital + roll risk already paid); assignment free. Accord Portrait implications governed by Art 06 §9.9.', 'Art 02 §8; Art 06 §9.9', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Effect duration', '✓', 'Immediate — AccordForm delivery is instantaneous. Resulting Accord\'s duration governed by Art 06 §9.3–§9.7 independently.', 'Art 04 §5 P19', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Persistence', '✓', '`persistence = Immediate` — no lingering game-state marker from Overture itself once the AccordForm is delivered; the resulting Accord\'s own persistence is a separate downstream concern (Art 06 §9.3–§9.7).', 'Art 04 §6.2', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Trigger validity', '⚠', 'Fires when its assigned host PA resolves (Beat 4) — trigger form `public_act.resolved(pa=X)` is new, not yet in confirmed TriggerExpr vocabulary (§6.3). Same category of gap as GD-01\'s district-scoped trigger (04-n27).', 'Art 04 §6.3; §11.1', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Portrait validity', '✓', '`portrait=None` — correctly typed (schema declares `portrait: dict[Faction, PortraitEntry]`, not Optional; empty dict is the right \"no entry\" representation, not `None`). No portrait entry for Overture\'s own assignment; Portrait implications for the resulting Accord governed separately by Art 06 §9.9.', 'Art 04 §6.1–§6.2; Art 06 §9.9', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Supported by zones', '✓ (N/A)', '`target_district=None` — Overture isn\'t a territory-scoped effect.', 'Art 01 §6–§7', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Supported by components', '✓', 'AccordForm (Art 06 §9.2). No new components.', 'Art 06 §9.2', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Assignment at Phase B; blank form delivered at Beat 4; faction drafts and places in Accord Placement Area at their discretion (no timing constraint; queued for next Debrief if placed outside Debrief window). Execution at Debrief per Art 06 §9.4. Delivery from ARBITER tableau: procedure in STD.CA.9 `arbiter_note`; deliver-from-tableau is consistent with existing ARBITER delivery subroutines, no novel behavior; Art 07 subroutine pass still needed to formalize.', 'Art 03 Phase B; Art 06 §9.4; STD.CA.9', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Data schema validation', '⚠', 'Required scaffolding fields present on sibling card GD-01 (`resolution_type`, `outcome_type`, `boost`, `ps_framing`, `target_freeform`) now present, matching GD-01 precedent; `value_rating` resolved to N/A. Trigger form still unconfirmed against §6.3 (see Trigger validity).', 'Art 04 §6.1–§6.3', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Card narrative', '✓', 'Grounded envelope-delivery scene; no mechanic restatement.', 'Art 04 §5 P26', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Outcome determinacy', '✓', '`Automatic`, single deterministic outcome (`success` only; `successcrit`/`fail`/`failcrit` all `None`).', 'Art 04 §5 P27', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Resource cost positioning', '✓ (N/A)', '`cost=None` — free assignment; the real cost was already paid via STD.CA.9\'s own resource tier. Mono/cross-resource distinction doesn\'t apply to a zero-cost effect.', 'Art 00a §9.2', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Trigger frequency (ModReactCard)', '⚠', 'Depends on how often STD.CA.9 succeeds and the faction chooses to assign the resulting Overture — a fairly rare, player-gated combination; best-effort, not independently verifiable here.', '', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Firing window (ModReactCard)', '✓', 'No other card shares this trigger shape (bound to one specific `assigned_pa` instance), so collision risk with other React cards is low.', '', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Automatic vs. d100 (ModReactCard)', '✓', 'Deterministic outcome-addition with no execution-quality dimension — `Automatic` is correct.', '', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Stack behavior (ModReactCard)', '⚠', 'A faction could plausibly hold multiple Overture copies (from multiple STD.CA.9 successes) and assign each to a different PA independently — not explicitly documented; same open-question category as the rest of the corpus.', '', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.1', 'Ring constraint (ModReactCard)', '✓ (N/A)', '`ring_constraint=None` — not ring-scoped; `faction=All` and Issued acquisition, no ring gating applies.', '', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.2', 'Action fit', '✓', 'A personal favor called in is a grounded expression of Ring 1/Core\'s institutional-access character (Art 00 §6.7), distinct from any faction\'s literal-force doctrine.', 'Art 00 §6.7; Art 04 §5a', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.2', 'Voice fit', '✓', '`faction=All`, no perspectives required (Standard card); narrative/tagline read in Core\'s institutional-proximity register.', 'Art 00 §6.7, §9', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.2', 'Doctrine alignment', 'N/A', 'No `target_faction`; `doctrine_mod` correctly absent — no faction relationship in play (Standard card, no faction doctrine to serve).', 'Art 04 §6.2', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.2', 'Card type fit', '✓', 'ModBattleCard/`subtype=Standard` correct; fills the Portable Asset-category naming slot for Ring 1.', 'Art 04 §6.1, §11.1', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.2', 'Taxonomy fit', 'N/A', 'Schema-locked None (§11.1).', 'Art 04 §6.2, §11.1', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.2', 'Balance', '✓', 'Weak Boost tier per the locked whole-subclass pattern; no cost step exists for this subclass; playtest-flagged (04-n94).', 'PM05 04-n94', '04___Card_System___Part3_Ring_Modifiers.md');
