INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.26', 'Card type fit', '✓', 'ModActionCard, `subtype=Standard`; correctly excluded from taxonomy (`layer`/`function`/`subject=None`) per §11.1 — parasitic on host, not its own action category.', 'Art 04 §6.1, §11.1', '04___Card_System___Part3_Ring_Modifiers.md');
