INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Action fit', '✓', 'Reactive claim-staking against a rival\'s move is a grounded competitive dynamic for a contested Ring; matches 04-53\'s \"available to whoever holds it\" intent.', 'Art 00 §7; 04-53', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Voice fit', '✓', '`narrative` reads in Core\'s institutional/proximity register. `perspectives=None` — live/per-card field for ModReactCard (§6.2), not blanket-None; whether faction-differentiated perspective text is warranted on identical-effect Standard cards is an open convention question, not a Voice fit failure.', 'Art 00 §6.7, §9', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Doctrine alignment', '✓', 'No `target_faction` — card doesn\'t act against a named rival, so `doctrine_mod=None` is trivially correct.', 'Art 04 §6.5', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Card type fit', '✓', 'ModReactCard/Standard/faction=All with real taxonomy — correctly classified per §6.1; available to any holder, distinct from Ghost\'s faction-locked presence-triggered cards.', 'Art 04 §6.1, §6.2', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Taxonomy fit', '✓', 'Independently verified against `ref_taxonomy.md`: Presence token\'s listed Layer is Territory; Layer×Function validity matrix (§5.1) confirms Territory×Add is valid.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Balance', '✓ (best-effort, pre-Art 00c)', 'value_rating 1, single chip, cost=None — at/below faction-specific power by design. Magnitude playtest-flagged like the rest of the set (04-n94).', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Effect duration', '✓', 'Immediate — fully resolved at trigger, no multi-Quarter temporary.', 'Art 04 §5 P19', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Persistence', '⚠ (deferred)', 'Field absent from spec. §6.2 lists persistence as live/per-card for ModReactCard, not None — but whether Immediate should be an explicit line or an implicit default for fire-and-consume cards is an open schema question (`schema_cleanup_log.md` #2), not resolved here.', 'Art 04 §6.2', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Trigger validity', '✓', '`presence_chip.placed(faction=opponent, ring=1)` — confirmed TriggerExpr vocabulary (§6.3), publicly observable board event.', 'Art 04 §6.3', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Portrait validity', '✓', 'Principle 11: Portrait fires when an action *strongly* aligns/opposes doctrine; grey areas produce none. This card\'s action (automatic, reactive, 1-chip, identical for every holder) is doctrinally neutral logistics for all five factions — no faction\'s doctrine is meaningfully expressed by holding or playing it. Justified absence documented uniformly across all five per the Standard-card portrait convention; distinct from DIR.MOD.9-style cards where the action is a deliberate, doctrinally-loaded choice.', 'Art 04 §6.2 P11', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Supported by zones', '✓', '`target_district=trigger.district`; ring context (`ring_constraint=1`, `ring_origin=1`) consistent.', 'Art 01 §6–7', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Supported by components', '✓', 'Presence chip is an existing component; `arbiter.place()` reuses the standard placement mechanism.', 'Art 02 §6–8', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Supported by game procedure', '✓', 'Trigger and response both reuse already-defined ARBITER chip-placement behavior — no novel procedure.', 'Art 03; GR 6.1', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Data schema validation', '⚠ (deferred)', 'Missing `persistence`/`resolution_type` — see Persistence row above; logged in `schema_cleanup_log.md`, not hand-fixed here to avoid a partial-fix inconsistency ahead of that decision. All other fields present and correctly typed.', 'Art 04 §6.1–§6.3', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Card narrative', '✓', 'Card Story states a concrete event (rival\'s chip placement → holder\'s matching claim); mechanic follows directly, no retrofit.', 'Art 04 §5 Card Story', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Outcome determinacy', '✓', 'Automatic, single success branch, no `game.choose_one()`.', 'Art 04 §5 P27', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Resource cost positioning', '✓ (N/A)', '`cost=None` — no resource cost to evaluate.', 'Art 00a §9.2', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Trigger frequency (ModReactCard)', '✓', 'Presence-chip placement in Ring 1 is a common recurring event; effect is modest (1 chip) — not overfire either.', '', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Firing window (ModReactCard)', '✓', 'No other Ring 1 ModReact card shares this exact trigger; STD.MOD.100 uses the removal side, not a race. (Cross-file collision against faction Ghost cards not checked — out of this batch\'s scope.)', '', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Automatic vs. d100 (ModReactCard)', '✓', 'Bounded, binary reaction — no execution-quality dimension to model via roll.', '', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Stack behavior (ModReactCard)', '⚠', 'Undocumented: does holding two copies double-fire on one rival placement? No restriction clause present. Genuinely open.', '', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.98', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=1` matches trigger scope; frequency supports a ring-locked card remaining playable.', '', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.99', 'Action fit', '✓', 'Bureaucratic retaliation for structure placement is a grounded competitive dynamic; matches 04-53\'s holder-agnostic intent.', 'Art 00 §7; 04-53', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.99', 'Voice fit', '✓', '`narrative` reads in Core\'s institutional register. Same open `perspectives=None` convention question as STD.MOD.98.', 'Art 00 §6.7', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.99', 'Doctrine alignment', '✓', '`target_faction=trigger.faction` IS set here (genuinely adversarial, unlike 98/100) — `doctrine_mod=None` is still correctly justified: `resolution=Automatic`/`threshold=None` means there\'s no roll for a threshold modifier to adjust; `doctrine_mod` only has meaning on d100 cards.', 'Art 04 §6.5', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.99', 'Card type fit', '✓', 'Same classification basis as STD.MOD.98.', 'Art 04 §6.1, §6.2', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.99', 'Taxonomy fit', '✓', 'Territory/Remove/PresenceToken — Territory×Remove confirmed valid in the Layer×Function matrix (§5.1).', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.99', 'Balance', '✓ (best-effort)', 'value_rating 2 — pricing model reads this above STD.MOD.98/100\'s tier despite the shared single-chip-removal shape; magnitude-mirror convention superseded for this card, single-chip removal, cost=None.', 'Art 02 §6–7', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.99', 'Effect duration', '✓', 'Immediate.', 'Art 04 §5 P19', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.99', 'Persistence', '⚠ (deferred)', 'Same open item as STD.MOD.98.', 'Art 04 §6.2', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.99', 'Trigger validity', '✓', '`structure_block.placed(faction=X, ring=Z)` matches confirmed §6.3 signature exactly.', 'Art 04 §6.3', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.99', 'Portrait validity', '✓', 'Same grey-area basis as STD.MOD.98, explicitly weighed against the adversarial angle here (this removes a rival\'s chip, unlike 98/100\'s pure self-benefit) — narrative frames it as procedural/bureaucratic, magnitude is minor (1 chip), no faction\'s doctrine is strongly expressed by holding or playing it. Uniform absence, all five factions.', 'Art 04 §6.2 P11', '04___Card_System___Part3_Ring_Modifiers.md');
