INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.101', 'Portrait validity', '⚠', 'Not the same grey-area shape as 98–100: this card converts a rival\'s *public, doctrinally significant* milestone (Dominant status) into a private intelligence gain for the holder. Unlike the earlier cards\' reflexive chip logistics, \"capitalizing on overheard institutional information\" reads as more deliberate — plausibly Portrait-relevant for at least Ghost (doctrine: understanding precedes action) if Ghost holds it. Genuinely uncertain rather than a settled absence — flagging rather than defaulting.', 'Art 04 §6.2 P11', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.101', 'Supported by zones', '✓', 'Same basis as STD.MOD.98.', 'Art 01 §6–7', '04___Card_System___Part3_Ring_Modifiers.md');
