INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.101', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Same basis as STD.MOD.98.', 'Art 03; GR 6.1', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.101', 'Data schema validation', '⚠ (deferred)', 'Persistence/resolution_type deferred (same as STD.MOD.98, still open — schema_cleanup_log #41). `faction(holder)` (used here as a Faction-object receiver passed positionally to `arbiter.deliver()`, mirroring Overture\'s established `faction(acting)` pattern) is now confirmed §6.3 MutationExpr vocabulary.', 'Art 04 §6.1–§6.3; 04-n171', '04___Card_System___Part3_Ring_Modifiers.md');
