INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Action fit', '✓', 'Bureaucratic obstruction of a rival\'s submission is a grounded Core-flavored premise.', 'Art 00 §7', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Voice fit', '✓', 'Same open `perspectives=None` note as STD.MOD.98.', 'Art 00 §6.7', '04___Card_System___Part3_Ring_Modifiers.md');
