INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Card type fit', '✓', 'Same classification basis as STD.MOD.98.', 'Art 04 §6.1, §6.2', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Taxonomy fit', '✓', 'Submission/Modify/PublicAct — Submission×Modify confirmed valid in the Layer×Function matrix. `function=Modify` also matches the actual mutation verb used (`arbiter.modify`) — internally consistent.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Balance', '✓ (best-effort)', 'value_rating 1 — pricing-model tier overrides the magnitude-mirror convention; −5 threshold (a real but moderate hindrance), cost=None.', 'Art 02 §6–7', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Effect duration', '✓', 'Immediate — the threshold penalty applies once, to one already-submitted PA.', 'Art 04 §5 P19', '04___Card_System___Part3_Ring_Modifiers.md');
