INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Portrait validity', '⚠', 'Deliberately obstructing a rival\'s Public Act is a more pointed adversarial choice than STD.MOD.98–102\'s passive logistics — plausibly doctrine-relevant (e.g., Directorate\'s \"control and restraint\" doctrine might read obstruction favorably; Ghost\'s \"understanding precedes action\" might read it as premature interference). Flagging as genuinely open rather than defaulting to None.', 'Art 04 §6.2 P11', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Supported by zones', '✓', 'Same basis as STD.MOD.98.', 'Art 01 §6–7', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Supported by components', '✓', 'No new component — modifies an existing submitted card\'s threshold field.', 'Art 02 §6–8', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: `arbiter.modify(target, threshold, delta)` isn\'t new ARBITER behavior — it feeds the existing threshold-modifier-accumulation pipeline already used by BM-xx tokens and M-11 Type B Countermeasure (Art 03 §9.4.1.1/§9.4.3.1.3).', 'Art 03 §9.4.1.1, §9.4.3.1.3', '04___Card_System___Part3_Ring_Modifiers.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('STD.MOD.103', 'Data schema validation', '⚠ (deferred)', 'Persistence/resolution_type deferred (same as STD.MOD.98, still open — schema_cleanup_log #41). `arbiter.modify(target, field, delta)` (procedurally grounded per the row above) is now confirmed §6.3 MutationExpr vocabulary.', 'Art 04 §6.1–§6.3; 04-n171', '04___Card_System___Part3_Ring_Modifiers.md');
