INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Action fit', '✓', 'Structural reinforcement as covert preparation — fortification work is done quietly before Beat 3 resolution window. Guild-exclusive competency; no other faction has the structural standing to claim total demolition immunity.', 'Art 00 §7; Art 04b §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Voice fit', '✓', '\"The Guild does not abandon what it has built\" is the doctrine statement. Network\'s \"what\'s inside them\" is the sharpest counter-perspective. Three perspectives only (Guild, Network, Directorate) — FactionSpecific card; Ghost and Syndicate absence acceptable.', 'Art 00 §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Doctrine alignment', '✓', 'Guild-exclusive card; structural defense is core Guild doctrine. Portrait submitter=+1 captures this. No opponent target → doctrine_mod N/A.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Card type fit', '✓', 'CovertOperation: fortification is covert prep. FactionSpecific (Guild): total immunity is Guild\'s unique structural competency, not available to others.', 'Art 04 §6.2; Art 04b §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Taxonomy fit', '✓', '`layer = Territory` — per Art 04b §4.6, Protect distributes to target\'s layer; target is StructureBlock (Territory). `function = Protect`, `subject = StructureBlock` — correctly scoped.', 'Art 04b §4.6, §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Balance', '✓', 'Beat 2 positional wager; wrong-read wastes slot. 1 Capacity cost. Immunity is total but Quarter-limited; one play protects one structure only.', 'Art 02 §7, §8', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Effect duration', '✓', 'Quarter-limited: immune flag persists until end of Quarter. Appropriate for a structural defense card.', '—', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Persistence', '✓', 'Immediate — card fully resolved at resolution beat; no lingering game-state marker', 'Art 04 §6', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Trigger validity', 'N/A', '`trigger = None` — Automatic at Beat 2.', '—', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Portrait validity', '✓', 'Guild `submitter=+1`. Fires on submission (DIR.PA.1). Submitter-scoped (DIR.PA.2). Single entry (NET.PA.1). Guild\'s structural-investment doctrine grounds the affinity.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Supported by zones', '✓', '`target_district = district.any`. Restriction: Guild structure in target district.', 'Art 01 §6, §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Supported by components', '✓', 'StructureBlock (restriction + immunity target); Capacity cost.', 'Art 02 §7, §8', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Supported by game procedure', '⚠', 'Submitted at Dispatch (Art 03 §9.1); Beat 2 row (Art 03 §9.4.0 Beat 0); immunity flag applied at Beat 3 when STD.CA.2 Demolish resolves (Art 03 §9.4.2 Beat 3). **Open:** Art 03 §9.4.2 Beat 2 covers Countermeasures and Protect only — no procedure defined for Fortify Structure immunity flag. Gap in Art 03.', 'Art 03 §9, §11', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Data schema validation', '⚠', '04-n70 (cited here) closed S95, stale reference — re-verified S154 via `audit_card_corpus.py` against current §6.1/§6.2: missing explicit declarations for `persistence_clearing_trigger`, `boost`, `on_accept`, `on_decline`, `on_discard`, `ps_framing`, `design_note`, `arbiter_note` (mostly `=None`-eligible — same corpus-wide Phase 0 D2 gap, not unique to this card). `card_id`/`doctrine_mod` are actually present — prior note was wrong, not just stale.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Card narrative', '⚠', 'Card Story block confirmed still empty (04-n79 genuinely open, not stale)', 'Art 04 §5 P26', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Outcome determinacy', '✓', '`Automatic`, single deterministic outcome (`success` only; `successcrit`/`fail`/`failcrit` all `None`).', 'Art 04 §5 P27', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.1', 'Resource cost positioning', '✓', 'Mono-resource (Capacity only, typed correctly).', 'Art 00a §9.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Action fit', '✓', 'Positioning to recover demolition costs before demolition happens — uniquely Guild, fits the game\'s economic-intelligence frame. Beat 2 commitment watching for opponent\'s Beat 3 action is a clean trigger structure.', 'Art 00 §7; Art 04b §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Voice fit', '✓', 'Three perspectives (Guild, Syndicate, Ghost) — FactionSpecific card; acceptable. Syndicate\'s \"we simply call it by a different name\" and Ghost\'s \"already told us what it knows\" both provide doctrinal depth.', 'Art 00 §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Doctrine alignment', '✓', '`target_faction = faction.opponent`, `doctrine_mod = None` — explicit design choice. Recovery amount mirrors STD.CA.2\'s cost regardless of doctrinal distance; the Guild gets paid the same whoever demolished. Correct.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Card type fit', '✓', 'CovertOperation: observation and positioning is covert; payment materializes via case mechanism. FactionSpecific (Guild): treating demolition as a Guild service is uniquely Guild doctrine.', 'Art 04 §6.2; Art 04b §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Taxonomy fit', '✓', '`layer = Economy` — returning NativeResource is capital flow, correctly Economy under Art 04b §4.4. `function = Add`, `subject = NativeResource` — trigger-context Add is the correct primitive.', 'Art 04b §4, §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Balance', '✓', 'Zero resource cost; action slot is the only cost. Trigger-contingent — wrong read wastes slot with no other penalty. First qualifying Demolish from named faction only.', 'Art 02 §8', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Effect duration', '✓', 'Instantaneous: resources delivered once when trigger fires. No persistent state.', '—', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Persistence', '✓', 'Immediate — card fully resolved at resolution beat; no lingering game-state marker', 'Art 04 §6', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Trigger validity', '✓', '`trigger = faction(target).completes(CovertOp, id=STD.CA.2)` — well-defined; ARBITER confirms at Beat 3. Note: `id=STD.CA.2` uses variable name, not integer — update to `id=2` when DB integers assigned (non-material; carry).', 'Art 04 (STD.CA.2)', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Portrait validity', '✓', 'Guild `submitter=+1`. Fires on submission (DIR.PA.1). Submitter-scoped (DIR.PA.2). Single entry (NET.PA.1).', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Supported by zones', 'N/A', '`target_district = None` — trigger monitors named opponent globally, not district-specific.', '—', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Supported by components', '✓', 'NativeResource (Art 02 §8); STD.CA.2 Demolish as trigger source.', 'Art 02 §8; Art 04 (STD.CA.2)', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Supported by game procedure', '✓', 'Submitted at Dispatch (Art 03 §9.1); placed in Beat 2 row (Art 03 §9.4.0 Beat 0); trigger fires when named faction completes STD.CA.2 at Beat 3 (Art 03 §9.4.2 Beat 3); delivery via ARBITER case (Art 07).', 'Art 03 §9, §11; Art 07', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Data schema validation', '⚠', '04-n70 (cited here) closed S95, stale reference — re-verified S154 via `audit_card_corpus.py` against current §6.1/§6.2: missing explicit declarations for `persistence_clearing_trigger`, `boost`, `on_accept`, `on_decline`, `on_discard`, `ps_framing`, `design_note`, `arbiter_note` (mostly `=None`-eligible — same corpus-wide Phase 0 D2 gap, not unique to this card). `card_id`/`doctrine_mod` are actually present — prior note was wrong, not just stale.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Card narrative', '⚠', 'Card Story block confirmed still empty (04-n79 genuinely open, not stale)', 'Art 04 §5 P26', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Outcome determinacy', '✓', '`Automatic`, single deterministic outcome (`success` only; `successcrit`/`fail`/`failcrit` all `None`).', 'Art 04 §5 P27', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.2', 'Resource cost positioning', '✓ (N/A)', '`cost=None` — the action slot itself is the wager.', 'Art 00a §9.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Action fit', '✓', 'First-entry territorial claim as covert operation — unannounced land assertion fits Guild\'s historical-precedence doctrine. The Directorate\'s jurisdictional counter makes the doctrinal tension mechanical rather than just narrative.', 'Art 00 §7; Art 04b §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Voice fit', '✓', '\"The Guild was here before the city had a name\" is the doctrine statement. Three perspectives (Guild, Network, Directorate) — FactionSpecific card; acceptable. Directorate\'s \"legal process, not archive\" is the sharpest counter.', 'Art 00 §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Doctrine alignment', '✓', 'Guild territorial-precedence doctrine (first-mover claim). Crit fail delivers Intel Token to Directorate — Directorate\'s regulatory oversight role is doctrinal, not incidental. Guild portrait submitter=+1 captures alignment. No opponent target → doctrine_mod N/A.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Card type fit', '✓', 'CovertOperation / FactionSpecific (Guild) — unannounced territorial claim. Covert until established.', 'Art 04 §6.2; Art 04b §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Taxonomy fit', '✓', '`layer = Territory` — placing first presence is a territorial operation. `function = Add`, `subject = PresenceToken` — correctly scoped. Crit success adds StructureBlock (stacks with success; same layer).', 'Art 04b §4, §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Balance', '⚠', 'Threshold 25 + ring_mod {0: −15} = effective threshold 10 in Ring 0. **Open:** Near-automatic for unclaimed Ring 0 districts — should first-entry be that easy? Consider raising base to 35–40. Crit success (presence + structure simultaneously) is a significant leap; confirm intent.', 'Art 01 §7; Art 02 §6, §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Effect duration', '✓', 'Permanent: presence and structure persist until removed.', '—', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Persistence', '✓', 'Immediate — card fully resolved at resolution beat; no lingering game-state marker', 'Art 04 §6', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Trigger validity', 'N/A', '`trigger = None`', '—', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Portrait validity', '✓', 'Guild `submitter=+1`. Fires on submission (DIR.PA.1). Submitter-scoped (DIR.PA.2). Single entry (NET.PA.1). `failcrit` dispatches IntelToken to Directorate — game effect, not Portrait shift (DIR.PA.2 clear).', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Supported by zones', '✓', '`target_district = district.any`. Restriction: total presence == 0 (unclaimed only).', 'Art 01 §6, §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Supported by components', '✓', 'PresenceToken (success); StructureBlock (crit success); Capacity cost; IntelToken to Directorate on crit fail.', 'Art 02 §6, §7, §8; Art 02 §12', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Supported by game procedure', '✓', 'Submitted at Dispatch (Art 03 §9.1); Beat 3 row (Art 03 §9.4.0 Beat 0); d100 threshold 25 with ring_mod; ARBITER silent IntelToken delivery to Directorate on crit fail (Art 03 §9.4.2 Beat 3; Art 07).', 'Art 03 §9, §11; Art 07', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Data schema validation', '⚠', '04-n70 (cited here) closed S95, stale reference — re-verified S154 via `audit_card_corpus.py` against current §6.1/§6.2: missing explicit declarations for `persistence_clearing_trigger`, `boost`, `on_accept`, `on_decline`, `on_discard`, `ps_framing`, `design_note`, `arbiter_note` (mostly `=None`-eligible — same corpus-wide Phase 0 D2 gap, not unique to this card). `card_id`/`doctrine_mod` are actually present — prior note was wrong, not just stale.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Card narrative', '⚠', 'Card Story block confirmed still empty (04-n79 genuinely open, not stale)', 'Art 04 §5 P26', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Outcome determinacy', '✓', '`d100`; success/successcrit/failcrit populated (fail=None), no `game.choose_one()` — resolves deterministically.', 'Art 04 §5 P27', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.3', 'Resource cost positioning', '✓', 'Mono-resource (Capacity only, typed correctly).', 'Art 00a §9.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Action fit', '✓', 'Rush construction without prior presence — unauthorized build is covert, high-risk, and distinctly Guild. Ghost and Syndicate as crit-fail beneficiaries is doctrinally perfect (the two most opportunistic actors).', 'Art 00 §7; Art 04b §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Voice fit', '✓', 'Three perspectives (Guild, Network, Ghost) — FactionSpecific card; acceptable. Ghost\'s \"better at covert operations than they admit\" is the sharpest outside read.', 'Art 00 §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Doctrine alignment', '✓', 'Guild construction doctrine (rush, without permission). Crit fail rewards Ghost (Intel Token) and Syndicate (district native) — explicitly doctrinal: the two most opportunistic actors benefit from Guild overreach. No opponent target → doctrine_mod N/A.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Card type fit', '✓', 'CovertOperation: unauthorized construction is covert until established. FactionSpecific (Guild): rush-build without prerequisites is exclusively Guild.', 'Art 04 §6.2; Art 04b §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Taxonomy fit', '✓', '`layer = Submission` — primary design intent is removing the STD.CA.1 presence prerequisite (a restriction on a CovertOperation); territorial outcomes (presence + structure) are the consequence, not the driver. `function = Modify` (\"alters cost, value, or attribute without changing fundamental state\") is the correct Function-vocabulary fit for waiving a prerequisite.', 'Art 04b §4, §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Balance', '✓', 'High cost (3 Capacity), high threshold (65). Crit fail rewards both Ghost (Intel Token) and Syndicate (district native) — asymmetric penalty for overreach. Net: saves STD.CA.3+STD.CA.1 sequential plays at the cost of one high-risk probabilistic slot.', 'Art 02 §6, §7, §8; Art 02 §12', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Effect duration', '✓', 'Permanent: presence and structure placed on success persist.', '—', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Persistence', '✓', 'Immediate — card fully resolved at resolution beat; no lingering game-state marker', 'Art 04 §6', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Trigger validity', 'N/A', '`trigger = None`', '—', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Portrait validity', '✓', 'Guild `submitter=+1`. Fires on submission (DIR.PA.1). Submitter-scoped (DIR.PA.2). Single entry (NET.PA.1). `failcrit` delivers IntelToken/native to opponents — game effects, not Portrait shifts (DIR.PA.2 clear).', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.4', 'Supported by zones', '✓', '`target_district = district.any`. Restriction: no existing Guild structure in target district. Ring mods apply normally.', 'Art 01 §6, §7', '04___Card_System___Part4a_Guild.md');
