INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.5', 'Action fit', '✓', 'Passive income from controlled infrastructure is the natural economic expression of Guild territorial control. Covert framing (yield not publicly attributed) fits the operations register.', 'Art 00 §7; Art 04b §5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.5', 'Voice fit', '✓', 'Three perspectives (Guild, Syndicate, Directorate) — FactionSpecific card; acceptable. Syndicate\'s \"billing us for the water\" is the sharpest outside read.', 'Art 00 §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.5', 'Doctrine alignment', '✓', 'Guild infrastructure-ownership doctrine — return on prior investment. Guild↔Syndicate are Opposed: Syndicate believes it should capture this yield, not the Guild (\"billing us for the water\"). No opponent target → doctrine_mod N/A; Syndicate portrait entry warrants consideration (see Portrait validity).', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
