INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.6', 'Resource cost positioning', '✓ (N/A)', '`cost=None` — the action slot itself is the wager, same shape as GUI.CA.2. Minor notation note: `success` achieves +2 native via two separate `add(1)` calls rather than a single `add(2)` — harmless, functionally correct, but inconsistent with corpus convention elsewhere.', 'Art 00a §9.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.7', 'Action fit', '✓', 'Coercive-but-compensated eviction is a clean territorial-response tool — fills the gap between Guild\'s building cards and having no answer to an opponent occupying ground Guild wants', 'Art 00 §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.7', 'Voice fit', '✓', 'Three perspectives (Guild acting, Directorate aligned, Ghost opposed) — Ghost\'s \"money and force, not strategy\" is the sharpest contrast to Guild\'s blunt-instrument approach', 'Art 00 §7, §9', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.7', 'Doctrine alignment', '✓', 'Guild only; paying compensation before displacing is on-doctrine for a faction whose identity runs through legitimate construction and process, even when the outcome is coercive', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
