INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.8', 'Data schema validation', '✓', 'All base fields now present. `success` converted from bare prose to a real structured MutationExpr. The retired \"Bribe\" mechanic the old design_note referenced left no trace in the spec and isn\'t reconstructed — the card is designed clean, strictly blind, as that note\'s own framing intended.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4a_Guild.md');
