INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Action fit', '✓', 'Guild\'s institutional weight guaranteeing a construction commitment in two districts — doctrinal expression of \"when Guild commits, it gets built\"', 'Art 00 §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Voice fit', '✓', 'Five perspectives: Guild matter-of-fact certainty; Directorate notes the institutional channel; Ghost reads it as operational pre-commitment; Network clocks the dual announcement; Syndicate prices the certainty premium', 'Art 00 §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Doctrine alignment', '✓', 'Guild ceiling Resolution card; Beat 2 Automatic; Portrait +1; construction certainty is the Guild doctrine made mechanical', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Card type fit', '✓', 'CovertOperation / FactionSpecific (Guild) — the guarantee is covert; no public announcement of which CA is being backed', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Taxonomy fit', '✓', 'Resolution / Modify / CovertOperation — suppresses d100 roll on a named target CA, converting it to guaranteed success+successcrit; the card modifies another Covert Operation\'s resolution, so Subject=CovertOperation is correctly-scoped, already-valid vocabulary.', 'Art 04b §4', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Balance', '⚠', 'High total cost (CA cost + 2C + 1 district native + 2 dispatch slots); ceiling output (4 presence + 2 structures for CA.4); restriction checks at Beat 0 limit abuse — playtesting required', 'Art 02 §6–§7', '04___Card_System___Part4a_Guild.md');
