INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Persistence', '✓', 'Immediate — guarantee resolves at Beat 3 with the target CA; no lingering marker', 'Art 04 §6', '04___Card_System___Part4a_Guild.md');
