INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Supported by zones', '✓', 'target_district = district B; named CA\'s own target_district = district A; both validated at Beat 0 per Art 01 §6.5', 'Art 01 §6.5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Supported by components', '✓', 'PresenceToken + StructureBlock output via named CA; no new components; cost from Guild resource pool. The card also declares `target_ca = ca.guild.beat3.d100` — a targeting field not in `design_reference_card_system.md`\'s documented Targeting field group (`target_district`/`target_faction`/`target_object`/`target_freeform`/`target_freeform`). Whether this needs to be a confirmed schema extension or should be re-expressed via `target_freeform` (which already exists for exactly this \"faction-declared free-form parameter\" purpose) isn\'t resolved.', 'Art 02 §6–§8', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Supported by game procedure', '⚠', 'Beat 0: ARBITER validates named CA and district B restriction; Beat 2: guarantee registered; Beat 3: named CA resolves without roll, output fires twice. Double-fire procedure is new — confirm against Art 03 §9.4', 'Art 03 §9.4', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Data schema validation', '⚠', '04-n70 (cited here) closed S95, stale reference — re-verified S154 via `audit_card_corpus.py` against current §6.1/§6.2: missing explicit declarations for `persistence_clearing_trigger`, `target_freeform`, `boost`, `on_accept`, `on_decline`, `on_discard`, `ps_framing` (mostly `=None`-eligible — same corpus-wide Phase 0 D2 gap, not unique to this card). `card_id` is actually present. `target_freeform` missing is expected — this card uses `target_ca` instead (04-n212, already tracked).', 'Art 04 §6.1–§6.3', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Card narrative', '⚠', 'Card Story block confirmed still empty (04-n79 genuinely open, not stale)', 'Art 04 §5 P26', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Outcome determinacy', '✓', '`Automatic`, single deterministic outcome (`success` only; `successcrit`/`fail`/`failcrit` all `None`) — the \"double-fire\" is two applications of the same success outcome, not a second resolution tier.', 'Art 04 §5 P27', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.CA.9', 'Resource cost positioning', '✓', 'Cross-resource (Capacity + district native, both typed correctly).', 'Art 00a §9.2', '04___Card_System___Part4a_Guild.md');
