INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Balance', '✓', '`cost = None` — reflexive, not a planned play; playtest-flagged (04-n94 pattern), not final.', 'Art 02 §6–§7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Effect duration', '✓', 'Immediate — chip placed back at trigger.', 'Art 04 §5 P19', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Persistence', '⚠', '`persistence` field open corpus-wide question (schema_cleanup_log item 2/D), not card-specific.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Trigger validity', '✓', '`presence_chip.removed(faction=X, district=Y)` is confirmed §6.3 vocabulary (PM05 04-n195 item 1) — the open gap tracked elsewhere (schema_cleanup_log #3) is specifically the `ring=` parameter on `.removed()`, which this card doesn\'t use. Trigger scope (any chip removal vs. specific action types) remains a separate open design question, not a vocabulary gap.', 'Art 04 §6.3', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Portrait validity', '✓', '`{Guild: submitter=+1}` — unchanged from fossil, already correctly structured.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Supported by zones', '✓', 'District-scoped by design — the whole point is returning to the specific district that lost the chip.', 'Art 01 §6–§7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Supported by components', '✓', 'Presence chips — existing component.', 'Art 02 §6, §11', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Chip removal is a publicly observable resolved action; no new ARBITER behavior needed.', 'Art 03 §18', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Data schema validation', '⚠', '`presence_chip.removed(...)` has no confirmed TriggerExpr vocabulary — same open gap as the rest of the corpus.', 'Art 04 §6.1–§6.3; PM05 04-n174', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Card narrative', '✓', 'Card Story present.', 'Art 04 §5 P26', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Outcome determinacy', '✓', '`Automatic` — deterministic reflex, no dice.', 'Art 04 §5 P27', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Resource cost positioning', '✓', '`cost=None` — free reflexive response, matching the \"we don\'t leave\" framing.', 'Art 00a §9.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Trigger frequency (ModReactCard)', '⚠', 'Depends on how often Guild chips get removed district-wide; best-effort, not independently verifiable here.', '', '04___Card_System___Part4a_Guild.md');
