INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Automatic vs. d100 (ModReactCard)', '✓', 'Deterministic reflex, no dice — Automatic is correct.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.1', 'Stack behavior (ModReactCard)', '⚠', 'Same open corpus-wide question: is a 2nd copy meaningful? Undocumented.', '', '04___Card_System___Part4a_Guild.md');
