INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Action fit', '✓', 'certification/permitting income keyed to a territorial milestone is a distinct, coherent fourth angle alongside build/demolish.', 'Art 00 §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Voice fit', '✓', 'Tagline and perspectives all read in Guild\'s transactional-but-thorough register.', 'Art 00 §6.7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Doctrine alignment', '✓', 'Guild submitter=+1 matches the scale of MOD.2/3/4/8.', 'Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Card type fit', '✓', 'ModReactCard/FactionSpecific (Guild), real taxonomy (Economy/Add/NativeResource, 04-n175) — matches MOD.2/3/4/8\'s shape.', 'Art 04 §6.1, §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Taxonomy fit', '✓', 'Economy×Add valid per the matrix, checked directly rather than just inherited from the family.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Balance', '✓', 'Flat +1 Capacity, no restriction, but keyed to a genuinely bounded event (Established-marker placement, one per faction per district, capped by 21 districts × 4 opponents) — less exposed to the \"least-gated/high-frequency\" concern flagged on GUI.MOD.2/4/8 since the trigger itself is inherently bounded.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Effect duration', '✓', 'Immediate — explicitly stated in the spec (`persistence=Immediate`), unlike most of the corpus where this field is absent.', 'Art 04 §5 P19', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Persistence', '✓', 'Explicitly declared (`persistence=Immediate, persistence_condition=None, persistence_effect=None`) — this card is ahead of the rest of the corpus on this field, not part of the deferred-field gap.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Trigger validity', '✓', '`established_marker.placed(faction=opponent)` — confirmed vocabulary, correctly scoped, no self-fire ambiguity.', 'Art 04 §6.3', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Portrait validity', '✓', 'submitter-bounded, correctly structured.', 'Art 04 §6.2 P11', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Supported by zones', '✓', '`target_district=trigger.district` — correct.', 'Art 01 §6–7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Supported by components', '✓', 'Standard resource-grant mechanism.', 'Art 02 §6–8', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Reuses existing Established-marker-placement event; no new ARBITER behavior.', 'Art 03; GR 6.1', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Data schema validation', '✓', 'Already scaffolding-complete — `ps_framing`, `boost`, `target_freeform` all explicitly declared (ahead of the rest of the corpus, which needed 04-n177 scaffolding added). Only `resolution_type` absent.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Card narrative', '✓', 'Card Story is concrete and well-formed (unlike most of the corpus, this was never a placeholder). `narrative` field itself is still `None`, but Card Story satisfies P26.', 'Art 04 §5 Card Story', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Outcome determinacy', '✓', 'Automatic, single success branch.', 'Art 04 §5 P27', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Resource cost positioning', '⚠', '`cost=None` — same whole-set Floor Act/value_rating gate as the rest of the corpus (04-n178).', 'Art 00a §9.2; PM05 04-n178', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Trigger frequency (ModReactCard)', '✓', 'moderate, front-loaded, bounded by 21 districts × 4 opponents — holds up.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Firing window (ModReactCard)', '✓', 'no other Guild MOD reacts to `established_marker.placed`; distinct from MOD.2\'s `structure_block.placed`. Holds up.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Automatic vs. d100 (ModReactCard)', '✓', 'unambiguous trigger, bounded flat yield.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Stack behavior (ModReactCard)', '⚠', 'Whether multiple copies fire independently is asserted, not derived from a documented rule — same open question as the rest of the corpus.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.9', 'Ring constraint (ModReactCard)', '✓', 'citywide, matching MOD.2\'s baseline.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Action fit', '✓', 'Guild committing construction priority to a contesting faction, transactionally rather than doctrinally, is a coherent, distinct mechanic from anything else in the set.', 'Art 00 §7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Voice fit', '✓', 'tagline and all 5 perspectives read correctly in-voice.', 'Art 00 §6.7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Doctrine alignment', '✓', 'Guild submitter=+1 only, no doctrine_mod — correctly reflects \"transactional, not political.\"', 'Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Card type fit', '⚠', 'ModReactCard/FactionSpecific is the right subclass, but `layer=None, function=None, subject=None` isn\'t a taxonomy gap to close later — it\'s a symptom of the deeper problem below.', 'Art 04 §6.1, §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Taxonomy fit', '⚠ **(blocker, 04-n176)**', '`arbiter.register_battlefield_modifier(...)` doesn\'t correspond to any Layer×Function pairing the taxonomy system supports. Direction: redesign, not a new category invented to fit it. This is the card\'s core blocker.', 'Art 04b §4; ref_taxonomy.md §5.1; PM05 04-n176', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Balance', '⚠', 'Fizzle risk (named faction may not still be contesting at §10) is a deliberate design tension, not a flaw — but genuinely hard to finalize while the taxonomy/mechanic itself is unresolved.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Effect duration', '✓', 'Seasonal correctly fits \"ongoing condition across multiple subsequent actions.\"', 'Art 04 §5 P19', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Persistence', '✓', 'Explicitly declared (`persistence=Seasonal`) — ahead of the rest of the corpus on this field.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Trigger validity', '✓', '`tension_marker.placed` confirmed §6.3 vocabulary.', 'Art 04 §6.3', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Portrait validity', '✓', 'submitter-bounded only, correctly excludes the named target_faction per P16.', 'Art 04 §6.2 P11', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Supported by zones', '✓', 'district + adjacency-based restriction ties this to real territorial investment.', 'Art 01 §6–7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Supported by components', '⚠', 'No physical marker/component represents the \"registered condition\" on the board beyond the card itself — tied to the same gap as the row below.', 'Art 02 §6–8', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Supported by game procedure', '⚠ **(blocker, 04-n148)**', 'Art 03 §10.1.2 has no step that reads a registered Guild condition and applies it. Per Governing Rule 6.1/Design Pillar 4.7b, new ARBITER behavior must be defined as a generalizable procedure *before* the card is finalized — as currently drafted, the card\'s `arbiter_note` describes behavior that doesn\'t yet exist as a defined procedure.', 'Art 03 §10.1.2; GR 6.1; Design Pillar 4.7b; PM05 04-n148', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Data schema validation', '⚠', '`layer/function/subject=None` (deliberate, tied to 04-n176) plus missing `resolution_type` (added as scaffolding).', 'Art 04 §6.1–§6.3', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Card narrative', '✓', 'Card Story is concrete and well-formed — the fizzle-risk narrative tension is genuinely the point, not a gap.', 'Art 04 §5 Card Story', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Outcome determinacy', '✓', 'Automatic; the fizzle-risk contingency is a real-world board-state dependency, not a hidden or probabilistic outcome — doesn\'t violate P27.', 'Art 04 §5 P27', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Resource cost positioning', '⚠', 'Real cost specified (Capacity×1) — not gated on 04-n178 the way cost-less cards are, but whether 1 Capacity is correctly priced for a ±2 Battlefield Strength swing can\'t be finalized while the mechanic itself is blocked on 04-n176.', 'Art 00a §9.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Trigger frequency (ModReactCard)', '✓', 'Contested is a specific, less-common board state — low-moderate frequency holds up.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Firing window (ModReactCard)', '✓', 'no race with other Guild MODs.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Automatic vs. d100 (ModReactCard)', '✓', 'Guild\'s registration action is unconditional; the eventual d10 battle roll is untouched.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as originally flagged — still open, not resolved.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.10', 'Ring constraint (ModReactCard)', '✓', 'redundant with the presence/adjacency restriction, correctly omitted.', '', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Action fit', '✓', 'Experienced crew leadership committed to a live contest is a grounded expression of Guild\'s construction doctrine (§5a).', 'Art 00 §7; Art 04 §5a', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Voice fit', '✓', 'Scoped to `narrative`/`arbiter_note` only (`perspectives`/`design_note` schema-locked None); construction-expertise register.', 'Art 00 §9', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Doctrine alignment', '✓', 'Boost via physical construction expertise; `doctrine_mod`/`target_faction` correctly None.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Card type fit', '✓', 'ModBattleCard/FactionSpecific correct; fills Guild\'s Asset-category naming slot; distinct from ModReactCard GUI.MOD.10.', 'Art 04 §6.1, §11.1', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Taxonomy fit', 'N/A', 'Schema-locked None (§11.1).', 'Art 04 §6.2, §11.1', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Balance', '✓', 'Weak Boost tier per the locked Boost/Hinder pattern; no cost step exists for this subclass; playtest-flagged (04-n94).', 'PM05 04-n94', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Effect duration', 'N/A', 'Immediate-resolution, discarded at §10.1.4 cleanup.', 'Art 04 §5 P19', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Persistence', 'N/A', 'Schema-locked None.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Trigger validity', 'N/A', 'Schema-locked None.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Portrait validity', '✓', '`portrait=None` is correct and permanent — ModBattleCard carries no portrait value, locked whole-subclass.', 'Art 04 §6.1–§6.2; PM02 L269', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Supported by zones', '✓', 'No `target_district`; `ring_constraint=None` correct for a faction-deck card.', 'Art 01 §6–§7', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Supported by components', '✓', 'No new components invoked.', 'Art 02', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Supported by game procedure', '✓', 'Prior `arbiter_note` was found fully redundant with the card\'s own fields and/or an already-existing, verified Art 03 procedure (S154 follow-up) and removed — card now carries no note and no comment, genuinely supported.', 'Art 03 §10.1.2, §10.1.4', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Data schema validation', '✓', '`ps_framing`/`boost`/`resolution_type` added as explicit None placeholders (04-n177 scaffolding).', 'Art 04 §6.1–§6.3; 04-n177', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Card narrative', '✓', 'Plain New Meridian event, no mechanic restatement.', 'Art 04 §5 Card Story', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Outcome determinacy', 'N/A', 'Schema-locked None.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.11', 'Resource cost positioning', 'N/A', '`cost=None` is the locked whole-subclass convention.', 'PM05 04-n94', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.12', 'Action fit', '✓', 'Committed physical material is a grounded expression of Guild\'s \"everything leaves a physical artifact\" doctrine (§5a).', 'Art 00 §7; Art 04 §5a', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.12', 'Voice fit', '✓', 'Scoped to `narrative`/`arbiter_note` only; material-logistics register, distinct from GUI.MOD.11\'s labor framing.', 'Art 00 §9', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.12', 'Doctrine alignment', '✓', 'Boost via physical material commitment; `doctrine_mod`/`target_faction` correctly None.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.12', 'Card type fit', '✓', 'ModBattleCard/FactionSpecific correct; fills Guild\'s Equipment-category naming slot.', 'Art 04 §6.1, §11.1', '04___Card_System___Part4a_Guild.md');
