INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.12', 'Effect duration', 'N/A', 'Immediate-resolution, discarded at §10.1.4 cleanup.', 'Art 04 §5 P19', '04___Card_System___Part4a_Guild.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.12', 'Persistence', 'N/A', 'Schema-locked None.', 'Art 04 §6.2', '04___Card_System___Part4a_Guild.md');
