INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.12', 'Supported by zones', '✓', 'No `target_district`; `ring_constraint=None` correct for a faction-deck card.', 'Art 01 §6–§7', '04___Card_System___Part4a_Guild.md');
