INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GUI.MOD.13', 'Voice fit', '✓', 'Scoped to `narrative`/`arbiter_note` only; procedural-friction register, no sabotage language.', 'Art 00 §9', '04___Card_System___Part4a_Guild.md');
