INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Action fit', '✓', 'Intelligence-into-action via operational interception — Ghost\'s prediction accuracy converts to execution, not just information. Fits Ghost doctrine: understanding precedes action, and in this case enables theft.', 'Art 00 §7; Art 04b §5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Voice fit', '✓', 'Ghost only; single perspective — interception as doctrine. Extended in v2.0 to include the \"theft\" framing.', 'Art 00 §7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Doctrine alignment', '✓', 'target_faction = faction.named; doctrine_mod = None — prediction accuracy is about intelligence depth, not doctrinal proximity.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Card type fit', '✓', 'CovertOperation / FactionSpecific (Ghost) — operation interception is Ghost-exclusive; no Standard equivalent.', 'Art 04 §6.2; Art 04b §5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Taxonomy fit', '⚠', 'Submission/Redirect/CovertOperation — Redirect communicates the mechanism (op moves from target lane to Ghost lane; no duplication). Needs Art 04b §5.1 validity matrix check (PM05 queued).', 'Art 04b §4, §5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Balance', '✓', '2 Findings for a triple-prediction. High prediction bar (faction + district + operation name) is the gate. Stolen op is free to Ghost — original faction bore the cost. Fizzle risk (wrong prediction OR can\'t execute) is the downside.', 'Art 02 §8', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Effect duration', '✓', 'Immediate: stolen op resolves at Beat 3, no persistent state from Pattern Match itself.', '—', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Persistence', '✓', 'Immediate — fully resolved at Beat 3; no lingering game-state marker from Pattern Match.', 'Art 04 §6', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Trigger validity', 'N/A', 'trigger = None — Automatic resolution: ARBITER checks the declared guess against grid at Beat 2.', '—', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Portrait validity', '⚠', 'Ghost submitter=+1, modifier=+1, mod_where=game.outcome == Success. Portrait AND/OR semantics still open (see Outstanding Issues). Additional open: does Portrait also fire when the stolen op resolves at Beat 3 under Ghost\'s lane?', 'Art 04 §6.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Supported by zones', '✓', 'target_district = district.named — Ghost names a specific district in the prediction. No adjacency restriction (analytical op).', 'Art 01 §6', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Supported by components', '✓', 'Findings cost; CovertOperation as redirect target; stolen op\'s components governed by that op\'s spec. Ghost may receive off-faction resources (Mandate, Capacity, etc.) — tradeable at Debrief.', 'Art 02 §8', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Supported by game procedure', '⚠', 'Beat 2 resolution; ARBITER checks prediction against covert grid; if match + executable: lane redirect. Art 03 gap: Pattern Match redirect procedure not yet written in Art 03 §9.4 — simpler than the prior copy-injection model but still unwritten.', 'Art 03 §9', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Data schema validation', '✓', '04-n70 closed S95 — stale \"Pending\" note corrected. `id`/`card_id`/`doctrine_mod`/`boost`/`ps_framing` all present. Audit-flagged base fields (`persistence_clearing_trigger`, `on_accept`, `on_decline`, `on_discard`) correctly resolve to `None`: Immediate persistence, `outcome_type` isn\'t `ElectPlayer`, not the evergreen card.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Card narrative', '✓', 'Card Story present', 'Art 04 §5 P26', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Outcome determinacy', '✓', '`Automatic` (`resolution_type = Transactional`); single deterministic outcome (`success` only; `successcrit`/`fail`/`failcrit` all `None`).', 'Art 04 §5 P27', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.1', 'Resource cost positioning', '✓', 'Mono-resource (Findings only, typed correctly).', 'Art 00a §9.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Action fit', '✓', 'Active surveillance of submitted operations — direct expression of Ghost\'s real-time intelligence doctrine. Distinct from STD.CA.5 Gather (historical intel) and GHO.CA.3 Dossier Breach (hand contents).', 'Art 00 §7; Art 04b §5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Voice fit', '✓', 'One perspective (Ghost only) — FactionSpecific; acceptable. \"We do not wait for the after-action report.\" Ghost\'s active-vs-passive intelligence distinction is clear.', 'Art 00 §7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Doctrine alignment', '✓', '`target_faction = faction(named_opponent)`, `doctrine_mod = None` — explicit design choice: surveillance effectiveness is about intelligence quality, not doctrinal proximity.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Card type fit', '✓', 'CovertOperation: active surveillance is covert. FactionSpecific (Ghost): real-time operational intel is Ghost\'s exclusive capability.', 'Art 04 §6.2; Art 04b §5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Taxonomy fit', '✓', '`layer = Information` — revealing the content of a submitted operation is Information layer. `function = Reveal`, `subject = CovertOperation` — correctly scoped.', 'Art 04b §4, §5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Balance', '✓', 'Mono-resource cost (Intel Token only) — the token itself covers the operational-depth cost; threshold 60. Intel Token consumed at submission regardless of outcome — meaningful downside for failed surveillance. Crit success stacks additional IntelToken on top of IntelDeliverySlip.', 'Art 02 §8; Art 02 §12', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Effect duration', '✓', 'Instantaneous: IntelDeliverySlip delivered once at Beat 2 resolution; reads target faction\'s Beat 3 grid column. IntelToken on crit. No persistent state beyond the delivered token.', '—', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Persistence', '✓', 'Immediate — card fully resolved at resolution beat; no lingering game-state marker', 'Art 04 §6', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Trigger validity', 'N/A', '`trigger = None`', '—', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Portrait validity', '✓', 'Ghost `submitter=+1`. Fires on submission (DIR.PA.1). Submitter-scoped (DIR.PA.2). Single entry (NET.PA.1). `failcrit = standing.remove(2)` is a PS shift (not Portrait — DIR.PA.2 clear).', 'Art 04 §6.2; Art 02 §11', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Supported by zones', 'N/A', '`target_district = None` — Intercept operates on submitted ops in the Resolution Grid, not a specific district.', '—', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Supported by components', '✓', 'IntelToken cost; Findings cost; IntelDeliverySlip (success); IntelToken (crit success); NotificationSlip (fail); PS −2 (failcrit).', 'Art 02 §8; Art 02 §11, §8', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Submitted at Dispatch (Art 03 §9.1); resolves Beat 2; reads Beat 3 grid column; d100 threshold 50; ARBITER delivers IS-xx via case (Art 07). Art 03 §9.4 Beat 2 Step 7a covers IS-xx delivery; Step 7b covers NotificationSlip; Step 7b.i covers failcrit.', 'Art 03 §9, §11; Art 07', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Data schema validation', '⚠', '04-n70 closed S95. `id`/`card_id`/`doctrine_mod` all present — prior note was wrong about that. Genuinely missing: `boost`, `ps_framing` (correctly resolve to `None` — no boost mechanic, no PS framing needed since only `failcrit` touches PS and that\'s a mechanical penalty, not a framed public act). `arbiter_note` was missing entirely; its content existed only as an Outstanding Issues bullet — moved into the field below.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Card narrative', '⚠', 'Pending 04-n79', 'Art 04 §5 P26', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Outcome determinacy', '✓', '`d100`; all four tiers populated (success/successcrit/fail/failcrit), no `game.choose_one()` — resolves deterministically.', 'Art 04 §5 P27', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.2', 'Resource cost positioning', '⚠', 'Mono (IntelToken only) — see Balance row. IntelToken-as-cost raises an open schema question about typing Intel Tokens as a cost resource — flagged, not resolved.', 'Art 00a §9.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.3', 'Action fit', '✓', 'SIGINT tap on dispatch channel — faction column read from Beat 3 grid; distinct from GHO.CA.2 (disrupts one submitted op), DIR.CA.3 (district row read), and STD.CA.5 (generates intel tokens); Ghost reads committed operations, not planning pool', 'Art 00 §7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.3', 'Voice fit', '✓', 'Faction-specific; single Ghost perspective by design — covert channel interception is Ghost-exclusive doctrine', 'Art 00 §7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.3', 'Doctrine alignment', '✓', 'Ghost only; Beat 2 commitment is the risk (spends before knowing target\'s submission); Automatic resolution fits signals intelligence work', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.3', 'Card type fit', '✓', 'CovertOperation / FactionSpecific (Ghost) — covert channel access is Ghost-exclusive', 'Art 04 §6.2; Art 04b §5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.3', 'Taxonomy fit', '✓', 'Information/Reveal/IntelDeliverySlip — DR-xx collapsed into IS-xx', 'Art 04b §4, §5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.3', 'Balance', '✓', '2 Findings, Automatic, Beat 2 — information advantage without dice risk; Beat 2 blind commitment is the cost; empty case = resources spent', 'Art 02 §6–§7', '04___Card_System___Part4b_Ghost.md');
