INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.15', 'Supported by zones', '✓', '`target_district` carries the guessed value directly when Ghost is predicting a district (mutually exclusive with `target_object` carrying it instead) — reuses the standard Targeting field group rather than a separate meta-declaration', 'Art 01 §6–§7', '04___Card_System___Part4b_Ghost.md');
