INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.15', 'Supported by game procedure', '⚠', '`resolution_grid.first_op(faction=X, beat=3)` (identifying the target\'s first-submitted Beat 3 operation) and `arbiter.corrupt(...)` (the overwrite itself) are new, unconfirmed §6.3 vocabulary — not previously used anywhere in the corpus. Both are minimal extensions of already-confirmed concepts (the Resolution Grid built at Beat 0; submission-order tiebreaking, Governing Rule 7.3b; Target Profile as a sanctioned Corrupt target, Art 04 §5 P24) rather than invented from nothing, but neither is formally defined as a general Art 03 procedure yet — flagged per Governing Rule 6.1, not resolved here.', 'Art 03 §9, §11; Governing Rule 6.1', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.15', 'Data schema validation', '✓', 'All base fields now present (`card_id`, `doctrine_mod`, `boost`, `ps_framing`, `persistence`, `portrait`, `perspectives` all filled or explicit `None`). `success` converted from bare prose to a structured conditional MutationExpr. Uses `target_freeform` — repurposed from the former `target_taxonomy` field and merged with the former `declared_params` field into one field (schema_cleanup_log #52, closes 04-n106) — for the replacement value.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.15', 'Card narrative', '✓', 'Card Story above; narrative/perspectives fields populated with 3 voices per `ref_card_types.md`\'s FactionSpecific convention', 'Art 04 §5 P26', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.15', 'Outcome determinacy', '✓', '`Automatic`; single `success` field carries an internal conditional (match/no-match) rather than a dice-driven success/fail split — a miss resolves as \"no effect, cost spent\" per the `fail=None` convention, not a separate branch', 'Art 04 §5 P27', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.CA.15', 'Resource cost positioning', '✓', 'Cross-resource (Findings + IntelToken), correctly typed; IntelToken scoped `about=target faction, status=[Fresh, Stale]` — ties the guess to real intelligence, not any held token', 'Art 00a §9.2', '04___Card_System___Part4b_Ghost.md');
