INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.1', 'Resource cost positioning', '✓ (N/A)', '`cost=None` — reasonable; the real cost is the intelligence-gathering prerequisite (Source Substitution/SIGINT chain), and misfire risk (card consumed on a wrong guess) already balances free activation.', 'Art 00a §9.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.1', 'Trigger frequency (ModReactCard)', '⚠', 'Depends on how often PAs are placed with Intel tokens attached — a fairly specific combined event; best-effort, not independently verifiable here.', '', '04___Card_System___Part4b_Ghost.md');
