INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.1', 'Automatic vs. d100 (ModReactCard)', '✓', 'Deterministic ARBITER check (no dice) — `Automatic` is correct.', '', '04___Card_System___Part4b_Ghost.md');
