INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.5', 'Data schema validation', '⚠ (deferred)', 'Scaffolding placeholders added (04-n177).', 'Art 04 §6.1–§6.3', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.5', 'Card narrative', '⚠', '`narrative` field empty; Card Story present above.', 'Art 04 §5 Card Story', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.5', 'Outcome determinacy', '✓', 'Automatic, single success branch, deterministic doubling formula.', 'Art 04 §5 P27', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.5', 'Resource cost positioning', '⚠', 'Real cost specified (Findings+Exposure) — but Exposure isn\'t Ghost\'s native resource; worth checking whether Ghost realistically holds it without a prior conversion step (cross-resource cost design, not illegal per se).', 'Art 00a §9.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.5', 'Trigger frequency (ModReactCard)', '✓ (best-effort)', 'Any faction\'s positive PS shift is a recurring event; gated by Ghost having the resources on hand to fire.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.5', 'Firing window (ModReactCard)', '✓', 'No other Ghost card shares this trigger.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.5', 'Automatic vs. d100 (ModReactCard)', '✓', 'Deterministic inversion formula, no execution-quality dimension.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.5', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as the rest of the corpus: 2 copies → quadruple the inversion? Undocumented.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.5', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct; not ring-scoped.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Action fit', '✓', 'Parasitic mirroring of a rival\'s economy fits Ghost\'s \"extract value without confrontation\" doctrine.', 'Art 00 §7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Voice fit', '✓', 'Tagline (\"their infrastructure is our logistics\") lands the doctrine. `narrative` field empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Doctrine alignment', '✓', '`portrait = None` — consistent with Ghost\'s invisibility preference for covert economic plays, same reasoning as GHO.MOD.5.', 'Art 04 §6.5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Card type fit', '✓', 'ModReactCard/Ghost, real taxonomy (Economy/Copy/NativeResource, 04-n175) — correctly Copy, not Add, per the design_note\'s own \"mirrored duplicate, not a transfer\" framing.', 'Art 04 §6.1, §6.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Taxonomy fit', '✓', 'Economy×Copy is valid per the matrix; Copy is the correct Function since this duplicates an effect chain rather than moving or creating new supply.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Balance', '⚠', 'Full mirrored draw for a 1-resource cost is potentially strong depending on the triggering faction\'s Upkeep yield — final read needs 04-n178 plus resolution of the cross-resource-holding question below.', 'Art 02 §6–7; Art 04 §6.5; PM05 04-n178', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Effect duration', '✓', 'Immediate.', 'Art 04 §5 P19', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Persistence', '⚠ (deferred)', 'Same open schema question as the rest of the corpus.', 'Art 04 §6.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Trigger validity', '⚠', '`resource.drawn_from_reservoir(faction=Any)` is a confirmed, already-documented gap (design_reference_card_system.md \"Still pending\" list) — not in the TriggerExpr schema at all. `faction=Any` self-fire is a confirmed-harmless case, not a factor here.', 'Art 04 §6.3', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Portrait validity', '✓', 'Empty `{}` justified per Doctrine alignment row.', 'Art 04 §6.2 P11', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Supported by zones', '✓', '`target_district=None` — correct; not a territory effect.', 'Art 01 §6–7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Supported by components', '✓', 'Resource delivery reuses the standard mechanism.', 'Art 02 §6–8', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Supported by game procedure', '⚠', 'Depends on Upkeep\'s resource-collection step being a detectable, reactable event — plausible given Upkeep is a defined phase, but the exact hook point isn\'t confirmed since the trigger term itself is unconfirmed (see Trigger validity).', 'Art 03; GR 6.1', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Data schema validation', '⚠ (deferred)', 'Scaffolding placeholders added (04-n177).', 'Art 04 §6.1–§6.3', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Card narrative', '⚠', '`narrative` field empty; Card Story present above.', 'Art 04 §5 Card Story', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Outcome determinacy', '✓', 'Automatic, single success branch.', 'Art 04 §5 P27', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Resource cost positioning', '⚠', 'Cost is denominated in the *triggering faction\'s* native resource — Ghost may not hold that resource type without a prior conversion/trade, same open question as GHO.MOD.5\'s Exposure cost.', 'Art 00a §9.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Trigger frequency (ModReactCard)', '⚠', 'Every faction draws resources at Upkeep every Quarter — potentially very high frequency if the trigger term is confirmed broadly. Ties directly into the Balance flag.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Firing window (ModReactCard)', '✓', 'No other Ghost card shares this trigger.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Automatic vs. d100 (ModReactCard)', '✓', 'Flat mirrored copy, no execution-quality dimension.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as the rest of the corpus: 2 copies → 2x the mirrored draw? Undocumented.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.6', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct; not ring-scoped.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Action fit', '✓', 'Endgame power-spike disruption via a dormant asset activating is a strong, doctrinally coherent Ghost beat — \"total control is just a convenient illusion\" lands the point precisely.', 'Art 00 §7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Voice fit', '✓', 'Tagline is one of the strongest in the set. `narrative` field empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Doctrine alignment', '✓', '`portrait = None` — consistent with Ghost\'s invisibility preference.', 'Art 04 §6.5', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Card type fit', '✓', 'ModReactCard/Ghost, real taxonomy (Territory/Redirect/PresenceToken, 04-n175).', 'Art 04 §6.1, §6.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Taxonomy fit', '✓', 'Territory×Redirect is valid per the matrix; Redirect is correct since ownership changes on the same chip-slot, matching the verb\'s definition (\"changes ownership, destination, or allegiance\").', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Balance', '⚠', 'Powerful, precisely-timed disruption of a Dominant achievement — high 3-resource cost plausibly balances it, but see the cross-resource-holding flag below; if Ghost can\'t reliably afford two foreign resource types, the effective cost (and thus balance) is unclear. Final read pending 04-n178.', 'Art 02 §6–7; Art 04 §6.5; PM05 04-n178', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Effect duration', '✓', 'Immediate.', 'Art 04 §5 P19', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Persistence', '⚠ (deferred)', 'Same open schema question as the rest of the corpus.', 'Art 04 §6.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Trigger validity', '✓', '`dominant_marker.placed(faction=Any)` is confirmed vocabulary, inclusive-of-self by default; firing against Ghost\'s own Dominant achievement costs 3 resources for a confirmed harmless no-op swap, not a bug.', 'Art 04 §6.3', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Portrait validity', '✓', 'Empty `{}` justified per Doctrine alignment row.', 'Art 04 §6.2 P11', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Supported by zones', '✓', '`target_district=trigger.district` — correct.', 'Art 01 §6–7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Supported by components', '✓', '`arbiter.remove(presence_chip,...)` confirmed to never target a Deployment Marker — no GR 8.3a conflict.', 'Art 02 §6–8; GR 8.3a', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Supported by game procedure', '✓', 'Reuses existing chip removal/placement mechanisms and the Dominant-marker-placement event; no new ARBITER procedure.', 'Art 03; GR 6.1', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Data schema validation', '⚠ (deferred)', 'Scaffolding placeholders added (04-n177).', 'Art 04 §6.1–§6.3', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Card narrative', '⚠', '`narrative` field empty; Card Story present above.', 'Art 04 §5 Card Story', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Outcome determinacy', '✓', 'Automatic, single success branch (two sequential mutations, no choose_one).', 'Art 04 §5 P27', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Resource cost positioning', '⚠', 'Real cost specified but spans 3 resource types, 2 of which (Capacity, Capital) aren\'t Ghost-native — the sharpest instance of the cross-resource-holding question raised at GHO.MOD.5/6.', 'Art 00a §9.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Trigger frequency (ModReactCard)', '✓ (best-effort)', 'Dominant-marker placement is inherently rare (endgame-adjacent), matching the design_note\'s own \"massive late-game state change\" framing — low frequency by design, not a flaw.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Firing window (ModReactCard)', '✓', 'No other Ghost card shares this trigger.', '', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.7', 'Automatic vs. d100 (ModReactCard)', '✓', 'Bounded, binary swap — no execution-quality dimension.', '', '04___Card_System___Part4b_Ghost.md');
