INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.8', 'Action fit', '✓', 'Mid-game expansion disruption via unnamed local assets fits Ghost\'s \"influence without visible presence\" doctrine, distinct from GHO.MOD.7\'s endgame-scale disruption.', 'Art 00 §7', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.8', 'Voice fit', '✓', 'Tagline reads correctly. `narrative` field empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4b_Ghost.md');
