INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.8', 'Card type fit', '✓', 'ModReactCard/Ghost, real taxonomy (Territory/Remove/PresenceToken, 04-n175), matches DIR.MOD.1\'s shape.', 'Art 04 §6.1, §6.2', '04___Card_System___Part4b_Ghost.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.8', 'Taxonomy fit', '✓', 'Territory×Remove — same verified matrix cell as the Directorate enforcement family.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4b_Ghost.md');
