INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.9', 'Action fit', '✓', 'Punitive counter-play against Intel-Token-funded PA submission; fits Ghost\'s information-as-leverage doctrine.', 'Art 00 §7', '04___Card_System___Part4b_Ghost.md');
