INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('GHO.MOD.9', 'Doctrine alignment', '✓', 'Punishing information misuse (Intel currency spent to force a PA through) is squarely Ghost\'s anonymity/leverage doctrine.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4b_Ghost.md');
