INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.8', 'Outcome determinacy', '✓', '`Automatic`, `outcome_type = ElectPlayer` — `on_accept`/`on_decline` both populated, no `game.choose_one()`, matching SYN.PA.1\'s confirmed pattern', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.8', 'Resource cost positioning', '✓', 'Cross-resource (Mandate + Intel Token), Mandate term correctly typed — Intel Token confirmed §6.3 vocabulary (schema_cleanup_log #10)', 'Art 00a §9.2; Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Action fit', '✓', 'Formal institutional presence-expansion act; ring-spread framing (\"radiates, doesn\'t concentrate\") matches Directorate\'s breadth-over-depth win path', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Voice fit', '✓', 'Directorate on-doctrine; Guild (aligned): expansion that doesn\'t overextend is sound planning; Network (opposed): authority spreading with nobody required to explain why', 'Art 00 §7, §9', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Doctrine alignment', '✓', 'Directorate-exclusive; closes a real, previously-audited doctrinal gap (04-n89) rather than duplicating an existing capability', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Card type fit', '✓', 'PublicAct / FactionSpecific (Directorate)', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
