INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Balance', '✓', 'Mandate × 2 for 1–3 tokens depending on N; design_note reasons the ceiling is modest (N caps at 2 by board geometry) and scales naturally from Standard-equivalent (0 Permanents) to Directorate\'s strongest late-game expansion tool', 'Art 02 §6–§7', '04___Card_System___Part4c_Directorate.md');
