INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Supported by zones', '✓', 'target_district = district.named; same-ring-adjacency check via `district.adjacent(...).where(ring==...)` — valid zone condition', 'Art 01 §6–§7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Supported by components', '✓', 'presence_chip — existing component; each placement respects the 6-chip-per-district cap (`cap_check=True`, Governing Rule 8.1)', 'Art 02 §6', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Design_note claims this reuses \"the same counting mechanism as CA.6 Institutional Audit / CA.7 Institutional Brief\" — checked directly, **true**: same `game.active_permanents(faction=, ring=)` call, now formalized as a confirmed §6.3 primitive (schema_cleanup_log #26, PM05 04-n201).', 'Art 03 §9, §11; Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Data schema validation', '⚠', 'Both `id` and `card_id` set (addresses #24). `narrative`/`perspectives` now populated (schema_cleanup_log #39). `arbiter_note = None` — unusual; every other reviewed card in this set carries at least a brief arbiter_note.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Card narrative', '⚠', 'Pending 04-n79; no Card Story block present. `narrative`/`perspectives` fields now populated (schema_cleanup_log #39).', 'Art 04 §5 P26', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Outcome determinacy', '✓', '`Automatic`; only `success` populated — no `game.choose_one()` or conditional branching (the `for_each`/`limit` construct iterates deterministically over a fixed board-state count, not a player choice). `outcome_type = Unilateral` present.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.9', 'Resource cost positioning', '✓', 'Mono-resource (Mandate × 2), correctly typed.', 'Art 00a §9.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Action fit', '✓', 'Public claim of institutional reach, scaled to actual board presence — fills a real, previously-audited gap (Directorate\'s only prior PS lever was covert)', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Voice fit', '✓', 'Directorate on-doctrine; Guild (aligned): a demonstrated number beats an asserted one; Network (opposed): a self-counted claim needs independent verification', 'Art 00 §7, §9', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Doctrine alignment', '✓', 'Directorate-exclusive; scaling by Established-district count is a direct, on-doctrine measure of institutional reach', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Card type fit', '✓', 'PublicAct / FactionSpecific (Directorate)', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Taxonomy fit', '✓', 'Standing / Shift / StandingMarker — matches `card_status` DB directly', 'Art 04b §4', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Balance', '✓', 'Flat threshold 50 (matches CA.2/CA.6/CA.7 precedent); cost kept cheap and mono (Mandate×2) — design_note reasons the real risk lives in the public reaction (N-scaled swing), not the resource spend', 'Art 02 §6–§7', '04___Card_System___Part4c_Directorate.md');
