INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Trigger validity', '✓', 'trigger = None — N/A', '—', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Portrait validity', '✓', 'Directorate submitter=+1, single entry', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Supported by zones', '✓', 'target_district = None — city-wide count, no single-zone reference; N derived from existing board-visible Established/Dominant markers', 'Art 01 §6–§7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Supported by components', '✓', 'No new component — counts existing Established markers already on board', 'Art 02 §6', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Supported by game procedure', '⚠', 'Design_note claims N uses \"the same counting mechanism CA.6/CA.7 use for Permanents.\" Checked directly: **not literally the same** — CA.6/CA.7 count active Directorate Permanent cards per ring (`game.active_permanents`), this card counts districts city-wide at Established+ tier (`district.where(influence_tier >= Established)`) — a different count entirely. The shared property is \"no ARBITER judgment call, simple physical tally\" (true for both), not an identical formula. Softer version of the Overture-pattern cross-card claim check — not confirmed false, but imprecisely worded.', 'Art 03 §9, §11; Governing Rule 6.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Data schema validation', '✓', 'Both `id` and `card_id` set (addresses #24). `narrative`/`perspectives` now populated (schema_cleanup_log #39). `outcome_type = Unilateral` — a self-contained PS shift with all four tiers populated, matching every sibling card in this file.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Card narrative', '⚠', 'Pending 04-n79; no Card Story block present. `narrative`/`perspectives` fields now populated (schema_cleanup_log #39).', 'Art 04 §5 P26', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Outcome determinacy', '✓', '`d100`; all four tiers populated (success/successcrit/fail/failcrit), no `game.choose_one()` — resolves deterministically once N and the roll are known.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.10', 'Resource cost positioning', '✓', 'Mono-resource (Mandate × 2), correctly typed.', 'Art 00a §9.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Action fit', '✓', 'Standing due-process institution — closes a real, long-open counter-card gap (04-n142) for Permanent PAs generally', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Voice fit', '✓', 'Directorate on-doctrine; Ghost (aligned): a process without a real cost isn\'t due process; Syndicate (opposed): a toll booth that still pays the tollkeeper when the challenge wins', 'Art 00 §7, §9', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Doctrine alignment', '✓', 'Directorate-exclusive; design_note explicitly frames this as extending CA.8\'s uniform-scrutiny principle from \"submits to suppression\" to \"regulations answer to due process\" — a genuine doctrinal throughline, not asserted in isolation', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Card type fit', '✓', 'PublicAct / FactionSpecific (Directorate)', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Taxonomy fit', '✓', 'Submission / Remove / PublicAct — matches `card_status` DB directly', 'Art 04b §4', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Balance', '✓', 'Directorate profits from every invocation (cost refund + Intel Token) regardless of who invokes it — design_note reasons this as a genuine income mechanism, not a giveaway, and nothing prevents Directorate re-declaring the removed PA later', 'Art 02 §6–§7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Effect duration', '✓', 'Permanent, no clearing condition — a standing institution once established, distinct from the other Permanent PAs it can be used against', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Persistence', '✓', 'Permanent; card-as-condition, `persistence_condition = None` deliberately (no auto-discard — a standing institution, not a conditional one)', 'Art 04 §6', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Trigger validity', '✓', 'No confirmed TriggerExpr vocabulary used — `persistence_effect` is a prose-described standing institution rather than a trigger/mutation pair; consistent with \"card IS the condition,\" not a reactive mechanism', 'Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Portrait validity', '✓', 'Directorate submitter=+1, single entry', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Supported by zones', '✓', 'target_district = None — game-wide scope, no single zone reference', 'Art 01 §6–§7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Supported by components', '✓', 'No new component — cost-match is a direct read of the target PA\'s own printed cost', 'Art 02 §6', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Self-policing per Governing Rule 6.1a; cost-match is a physical lookup, not an ARBITER calculation (GR 6.1/4.7b-safe, explicitly reasoned in design_note)', 'Art 03 §9; Governing Rule 6.1, 6.1a', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Data schema validation', '✓', 'Both `id` and `card_id` set (addresses #24). `narrative`/`perspectives` now populated (schema_cleanup_log #39). `resolution_type` corrected `Permanent public act`→`Transactional`, same basis as DIR.PA.5/DIR.PA.6 (schema_cleanup_log #41).', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Card narrative', '⚠', 'Pending 04-n79; no Card Story block present. `narrative`/`perspectives` fields now populated (schema_cleanup_log #39).', 'Art 04 §5 P26', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Outcome determinacy', '✓', '`Automatic`; only `success` populated (a flat PS +1 for establishing the institution) — no `game.choose_one()` or conditional branching. `outcome_type = Unilateral` present.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.PA.11', 'Resource cost positioning', '✓', 'Mono-resource (Mandate × 2), correctly typed.', 'Art 00a §9.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Action fit', '✓', 'Institutional enforcement against unauthorized presence placement fits Directorate\'s control/continuity doctrine directly.', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Voice fit', '✓', 'Tagline/name read in Directorate\'s institutional-enforcement register. `narrative` field itself is empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Doctrine alignment', '✓', 'Portrait submitter=+1 rewards Directorate for exercising jurisdictional authority — directly expresses doctrine when played.', 'Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Card type fit', '✓', 'ModReactCard/Directorate with real taxonomy (Territory/Remove/PresenceToken, 04-n175) — correctly classified per §6.1.', 'Art 04 §6.1, §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Taxonomy fit', '✓', 'Verified against `ref_taxonomy.md`: PresenceToken\'s Layer is Territory; Layer×Function matrix confirms Territory×Remove valid.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Balance', '⚠', 'Single-chip, Immediate, Established-gated — plausible on its face, but cost is an open TBD (see Resource cost positioning); can\'t finalize balance until 04-n178 resolves the value_rating→cost model.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Effect duration', '✓', 'Immediate — fully resolved at trigger, no lingering marker.', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Persistence', '⚠ (deferred)', 'Field absent from spec, same open schema question as the Ring set (implicit-default-Immediate vs. explicit line), not resolved here.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Trigger validity', '✓', '`presence_chip.placed(faction=Any)` is confirmed TriggerExpr vocabulary (§6.3). `faction=Any` is inclusive-of-self by default; Directorate\'s own placements also satisfying the trigger is intentional self-policing, a harmless costed no-op, not a bug.', 'Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Portrait validity', '✓', '`{Directorate: submitter=+1}` is submitter-bounded, correctly structured per P16.', 'Art 04 §6.2 P11', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Supported by zones', '✓', '`target_district=trigger.district`; no ring constraint, consistent with an Established-gated (not ring-gated) mechanism.', 'Art 01 §6–7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Supported by components', '✓', 'Presence chip removal reuses the standard mechanism; `arbiter.remove(presence_chip,...)` is confirmed to never target a Deployment Marker, so no GR 8.3a conflict.', 'Art 02 §6–8; GR 8.3a', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Reuses existing chip-removal behavior; no new ARBITER procedure needed.', 'Art 03; GR 6.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Data schema validation', '⚠ (deferred)', 'Scaffolded (04-n177): `ps_framing`/`boost`/`resolution_type` now present as placeholders, not filled with real values; `cost` remains a TBD comment.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Card narrative', '⚠', 'Card Story above gives a concrete event, but the in-card `narrative` prose field is still empty — narrative-writing pass still needed.', 'Art 04 §5 Card Story', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Outcome determinacy', '✓', 'Automatic, single success branch, no `game.choose_one()`.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Resource cost positioning', '⚠', '`cost=None` with a TBD comment (\"possibly 1 Mandate\") — cannot close this row card-by-card; gated on 04-n178 (Floor Act singularity + value_rating-derived cost, whole-set decision).', 'Art 00a §9.2; PM05 04-n178', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Trigger frequency (ModReactCard)', '✓ (best-effort)', 'Presence-chip placement is common; Established-gate and single-chip yield keep the effect modest. Final read pending 04-n178.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Firing window (ModReactCard)', '⚠', 'DIR.MOD.2 (Syndicate-narrowed) and DIR.MOD.3 (Ring 1, no gate) share overlapping trigger space with this card. No documented rule on whether all three fire off the same single placement event if Directorate holds the full family.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Automatic vs. d100 (ModReactCard)', '✓', 'Bounded institutional-authority action, no execution-quality dimension to model via roll.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as the Ring set: does holding 2 copies double-fire on one rival placement? Undocumented.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.1', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct, since this variant is gated by Established status, not ring; correctly distinguishes from DIR.MOD.3 (ring-locked).', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Action fit', '✓', 'Faction-targeted institutional enforcement; design_note frames Syndicate as Directorate\'s primary doctrinal territorial adversary — grounded, not arbitrary narrowing.', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Voice fit', '✓', 'Tagline reads in Directorate\'s register. `narrative` field itself is empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Doctrine alignment', '✓', 'Directorate submitter=+1 correctly expresses doctrine on play.', 'Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Card type fit', '✓', 'Same shape as DIR.MOD.1 — ModReactCard/Directorate, real taxonomy, correctly classified.', 'Art 04 §6.1, §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Taxonomy fit', '✓', 'Territory/Remove/PresenceToken — same verified matrix cell as DIR.MOD.1.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Balance', '⚠', 'Narrower trigger than DIR.MOD.1 (Syndicate-only), so lower frequency — plausible, but final read gated on 04-n178 like the rest of the family.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Effect duration', '✓', 'Immediate.', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Persistence', '⚠ (deferred)', 'Same open schema question as DIR.MOD.1.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Trigger validity', '✓', '`presence_chip.placed(faction=Syndicate)` — confirmed vocabulary, explicitly scoped, no self-fire ambiguity (Directorate ≠ Syndicate).', 'Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Portrait validity', '✓', '`{Directorate: submitter=+1}` only. The `Syndicate: flat=-1` target-faction entry removed (schema_cleanup_log #7 Q2) — Andy\'s ruling: Portrait reflects only the acting faction\'s own doctrine, never a consequence imposed on a target.', 'Art 04 §6.2 P11', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Supported by zones', '✓', 'Same as DIR.MOD.1.', 'Art 01 §6–7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Supported by components', '✓', '`arbiter.remove(presence_chip,...)` confirmed to never target a Deployment Marker — no GR 8.3a conflict, family-wide resolution.', 'Art 02 §6–8; GR 8.3a', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Supported by game procedure', '✓ (contingent)', 'Same as DIR.MOD.1.', 'Art 03; GR 6.1', '04___Card_System___Part4c_Directorate.md');
