INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Resource cost positioning', '⚠', '`cost=None`, no TBD comment — inconsistent with DIR.MOD.1\'s explicit doubt on the identical mechanism. Both gated on 04-n178; the inconsistency itself is worth flagging so the eventual cost model applies uniformly across the family.', 'Art 00a §9.2; PM05 04-n178', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Trigger frequency (ModReactCard)', '✓ (best-effort)', 'Syndicate-only scope keeps frequency lower than DIR.MOD.1\'s generic trigger.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Firing window (ModReactCard)', '⚠', 'Same family-overlap flag as DIR.MOD.1 — no documented rule for simultaneous fire if Directorate holds the full 1/2/3 set.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Automatic vs. d100 (ModReactCard)', '✓', 'Same as DIR.MOD.1.', '', '04___Card_System___Part4c_Directorate.md');
