INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.2', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct; this variant is gated by faction identity, not ring.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Action fit', '✓', 'Unrestricted home-territory authority is a coherent, distinct escalation from DIR.MOD.1/2 — not a redundant reprint.', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Voice fit', '✓', 'Tagline (\"does not require a justification\") lands the doctrine cleanly. `narrative` field itself empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Doctrine alignment', '✓', 'Portrait submitter=+1; correctly expresses \"Core is structural, not earned\" doctrine framing.', 'Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Card type fit', '✓', 'Same shape as DIR.MOD.1/2.', 'Art 04 §6.1, §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Taxonomy fit', '✓', 'Territory/Remove/PresenceToken — same verified matrix cell.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Balance', '⚠', 'Strongest of the family (no restriction) — reasonable given Ring-lock narrows scope to Core only, but final read gated on 04-n178 like its siblings.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Effect duration', '✓', 'Immediate.', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Persistence', '⚠ (deferred)', 'Same open schema question as DIR.MOD.1/2.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Trigger validity', '✓', 'Same `faction=Any` scope as DIR.MOD.1 — inclusive-of-self by default, harmless costed no-op here too.', 'Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Portrait validity', '✓', '`{Directorate: submitter=+1}` only — no target-faction entry, so DIR.MOD.2\'s Item 7 question doesn\'t apply here.', 'Art 04 §6.2 P11', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Supported by zones', '✓', '`ring_constraint=1` matches trigger\'s `ring=1` scope; consistent.', 'Art 01 §6–7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Supported by components', '✓', '`arbiter.remove(presence_chip,...)` confirmed to never target a Deployment Marker — no GR 8.3a conflict, family-wide resolution.', 'Art 02 §6–8; GR 8.3a', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Same as siblings.', 'Art 03; GR 6.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Data schema validation', '⚠ (deferred)', 'Scaffolded (04-n177) — placeholders only.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Card narrative', '⚠', '`narrative` field empty; Card Story above is new this pass.', 'Art 04 §5 Card Story', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Outcome determinacy', '✓', 'Automatic, single success branch.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Resource cost positioning', '⚠', '`cost=None`, no TBD note — same family inconsistency flagged at DIR.MOD.2 (DIR.MOD.1 flags doubt on the identical mechanism, 2/3 don\'t). Gated on 04-n178.', 'Art 00a §9.2; PM05 04-n178', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Trigger frequency (ModReactCard)', '⚠', 'Ring-locked to Core (fewer districts, but institutionally dense — Core is where most factions eventually push). Combined with no restriction, this may be the highest-frequency card in the family; final read pending 04-n178.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Firing window (ModReactCard)', '⚠', 'Same family-overlap flag as DIR.MOD.1/2 — if a Core placement also satisfies DIR.MOD.1\'s generic trigger, no documented rule on whether both fire.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Automatic vs. d100 (ModReactCard)', '✓', 'Same as siblings.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as DIR.MOD.1/2.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.3', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=1` correctly matches trigger scope; distinguishes this as the ring-locked family member.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Action fit', '✓', 'Bureaucratic rent-seeking on diplomatic activity is a grounded, distinct Directorate income lever — doesn\'t overlap DIR.MOD.5\'s shape (permanent-PA-triggered, not Accord-triggered).', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Voice fit', '✓', 'Tagline reads as institutional overhead, not favoritism. `narrative` field empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Doctrine alignment', '✓', 'Portrait submitter=+1; Directorate\'s continuity/control doctrine extends naturally to \"we tax the paperwork.\"', 'Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Card type fit', '✓', 'ModReactCard/Directorate, real taxonomy (Economy/Add/NativeResource, 04-n175).', 'Art 04 §6.1, §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Taxonomy fit', '✓', 'NativeResource\'s typical Layer is Economy; Layer×Function matrix confirms Economy×Add valid.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Balance', '⚠', 'Flat, low-value (+1), no cost — plausible as a minor economic engine, but frequency is entirely dependent on other factions\' Accord activity (could be zero in a quiet game). Final read pending 04-n178 alongside the rest of the set.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Effect duration', '✓', 'Immediate.', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Persistence', '⚠ (deferred)', 'Same open schema question as the enforcement family.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Trigger validity', '✓', '`accord.placed` is confirmed TriggerExpr vocabulary (§6.3), publicly observable, no faction-scoping ambiguity (unscoped by design — fires on any Accord).', 'Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Portrait validity', '✓', '`{Directorate: submitter=+1}` — submitter-bounded, correctly structured.', 'Art 04 §6.2 P11', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Supported by zones', '✓', '`target_district=None` — correct; Accords have no district dimension.', 'Art 01 §6–7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Supported by components', '✓', '`faction(Directorate).mandate.add()` reuses the standard resource-grant mechanism; no component conflict (unlike the enforcement family\'s marker-removal edge).', 'Art 02 §6–8', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: No novel procedure — Accord formation is already a defined board event.', 'Art 03; GR 6.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Data schema validation', '⚠ (deferred)', 'Scaffolded (04-n177) — placeholders only.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Card narrative', '⚠', '`narrative` field empty; Card Story above is new this pass.', 'Art 04 §5 Card Story', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Outcome determinacy', '✓', 'Automatic, single success branch.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Resource cost positioning', '⚠ (N/A pending 04-n178)', '`cost=None` — plausible for a low-value passive-style engine card, but the eventual Floor Act/value_rating decision (04-n178) determines whether any non-Floor-Act card can carry `cost=None`, this one included.', 'Art 00a §9.2; PM05 04-n178', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Trigger frequency (ModReactCard)', '⚠', 'Entirely dependent on Accord-formation rate, which is player-driven and not guaranteed — genuinely variable, not a design flaw, but worth tracking in playtest.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Firing window (ModReactCard)', '✓', 'No other Directorate card shares this trigger; no overlap with the enforcement family.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Automatic vs. d100 (ModReactCard)', '✓', 'Flat administrative fee, no execution-quality dimension.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as the rest of the set: does holding 2 copies double the yield on one Accord? Undocumented.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.4', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct; Accords aren\'t ring-scoped.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Action fit', '✓', 'Self-subsidy tied to Directorate\'s own costly commitment is a coherent \"institutional scale needs institutional funding\" beat, distinct from DIR.MOD.4\'s Accord-tax shape.', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Voice fit', '✓', 'Tagline lands the doctrine. `narrative` field empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Doctrine alignment', '✓', '`portrait = None` — no entry at all, correctly justified: this is Directorate subsidizing its own already-doctrinal action, nothing new is being expressed about doctrine at the moment of the subsidy itself.', 'Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Card type fit', '✓', 'ModReactCard/Directorate, real taxonomy (Economy/Add/NativeResource, 04-n175).', 'Art 04 §6.1, §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Taxonomy fit', '✓', 'Same verified Economy×Add cell as DIR.MOD.4.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Balance', '✓', 'Checked for exploit potential: fires only on Directorate\'s own Permanent PA placements, inherently rare and individually costly — a rebate, not a loop. Reasonable as specced.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Effect duration', '✓', 'Immediate — the subsidy itself resolves once; the triggering PA\'s own Permanent persistence is a separate card\'s property.', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Persistence', '⚠ (deferred)', 'Same open schema question as the rest of the set.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Trigger validity', '✓', '`public_act.placed_on_frg(faction=Directorate, persistence=Permanent)` — confirmed vocabulary (§6.3), explicitly self-scoped by design, no ambiguity.', 'Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
