INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Supported by components', '✓', 'Standard resource-grant mechanism, no component conflict.', 'Art 02 §6–8', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Supported by game procedure', '✓', 'Reuses the existing §9.2 Public Declaration/FRG-placement event; no new ARBITER procedure.', 'Art 03; GR 6.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Data schema validation', '⚠ (deferred)', 'Scaffolded (04-n177) — placeholders only.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Card narrative', '⚠', '`narrative` field empty; Card Story above is new this pass.', 'Art 04 §5 Card Story', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Outcome determinacy', '✓', 'Automatic, single success branch.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Resource cost positioning', '⚠ (N/A pending 04-n178)', '`cost=None` — same as DIR.MOD.4, awaiting the whole-set Floor Act/value_rating decision before any non-Floor-Act card\'s `cost=None` can be confirmed correct.', 'Art 00a §9.2; PM05 04-n178', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Trigger frequency (ModReactCard)', '✓', 'Bounded by how many Permanent PAs Directorate ever places — inherently low-frequency, matching the \"rare subsidy\" design intent.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Firing window (ModReactCard)', '✓', 'No other Directorate card shares this trigger.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Automatic vs. d100 (ModReactCard)', '✓', 'Flat subsidy, no execution-quality dimension.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as the rest of the set: 2 copies → double subsidy per Permanent PA placed? Undocumented.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.5', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct; not a district-scoped effect.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Action fit', '✓', 'Directorate declaring a broad emergency constraint off a World Event matches the confirmed principle: standing-condition \"law\" cards may legitimately affect everybody, unlike Immediate-effect cards which should target specifically.', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Voice fit', '✓', 'Tagline (\"the Directorate dictates how\") reads correctly. `narrative` field empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Doctrine alignment', '⚠', '`portrait = None` — no entry. This looks like the wrong call: this is arguably the strongest single doctrinal expression in the set (invoking emergency powers table-wide), and Principle 11 exists precisely for actions that *strongly* express a faction\'s doctrine. Distinct from DIR.MOD.5\'s justified-empty case. Flag: should carry at least `{Directorate: submitter=+1}`.', 'Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Card type fit', '✓', 'ModReactCard/Directorate, `persistence=Seasonal` correctly using the confirmed card-as-standing-condition-on-FRG pattern (04-n145).', 'Art 04 §6.1, §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Taxonomy fit', '✓', 'Submission/Modify/PublicAct — re-derived directly against DIR.PA.1 rather than assumed; confirmed against the matrix (Submission×Modify valid).', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Balance', '⚠ (blocked — XA-54)', '−10 to any qualifying opponent PA is significant, partially offset by a real Mandate+Exposure cost, but frequency is entirely unknown until Broadcast Card/World Event content exists. Cannot close.', 'Art 02 §6–7; Art 04 §6.5; PM05 XA-54', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Effect duration', '✓', '`persistence = Seasonal` correctly typed for \"remains until Quarter end.\"', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Persistence', '✓', 'Unlike the rest of the set, this card *does* specify `persistence` explicitly and correctly (Seasonal) — not part of the deferred-field gap.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Trigger validity', '⚠ (blocked — XA-54)', '`world_event.played` is confirmed §6.3 vocabulary as a term, but ungrounded — no Broadcast Card taxonomy exists yet to define what qualifies as a \"World Event\" or how often one occurs.', 'Art 04 §6.3; PM05 XA-54', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Portrait validity', '⚠', 'See Doctrine alignment row — same finding, `{}` likely wrong for this card specifically.', 'Art 04 §6.2 P11', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Supported by zones', '✓', '`target_district=None` — correct; this is a global effect, not district-scoped, matching the \"law\" framing.', 'Art 01 §6–7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Supported by components', '✓', 'Card-as-condition on FRG, no separate marker needed — reuses the confirmed Seasonal pattern.', 'Art 02 §6–8', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Supported by game procedure', '⚠ (blocked — XA-54)', 'Depends on a World Event/Broadcast Card reveal procedure that doesn\'t fully exist; XA-54 also flags the open question of whether \"Emergency\" should be a formal Broadcast Card subtype (rare, high-narrative-specificity) or any World Event qualifies (fires every Situation Report phase) — a balance-relevant procedural gap, not just content.', 'Art 03; GR 6.1; PM05 XA-54', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Data schema validation', '✓', '`persistence_effect = game.board_condition(scope=, effect=on(TriggerExpr): MutationExpr)` — valid confirmed MutationExpr, matching the existing board-condition precedent used elsewhere in the corpus. `success=None`; the card\'s one-time trigger action is establishing the standing condition itself, no separate immediate mutation.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Card narrative', '⚠', '`narrative` field empty; Card Story above is new this pass.', 'Art 04 §5 Card Story', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Outcome determinacy', '✓', 'Automatic, single branch (establishes a standing condition) — the *effect* the standing condition applies isn\'t itself probabilistic.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Resource cost positioning', '⚠ (blocked — XA-54)', 'Cost is specified (Mandate+Exposure, not the 04-n178 Floor-Act gate this time) — but whether the cost is positioned correctly can\'t be judged without knowing trigger frequency.', 'Art 00a §9.2; PM05 XA-54', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Trigger frequency (ModReactCard)', '⚠ (blocked — XA-54)', 'Entirely dependent on undesigned Broadcast Card/World Event content — could be common or vanishingly rare. Cannot close.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Firing window (ModReactCard)', '✓', 'No other Directorate card shares this trigger.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Automatic vs. d100 (ModReactCard)', '✓', 'Establishing a standing condition is binary; no execution-quality dimension.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Stack behavior (ModReactCard)', '⚠', 'More complex than the rest of the set: since this creates a Seasonal standing condition rather than firing-and-consuming, does a 2nd copy stack a further −10, or is it wasted once the condition already exists? Undocumented, and a sharper question than the generic \"2 copies\" flag elsewhere.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.6', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct; global effect, not ring-scoped.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Action fit', '✓', 'Claiming jurisdictional oversight over new construction is a clean, doctrinally grounded expression of institutional authority.', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Voice fit', '✓', 'Tagline reads correctly. `narrative` field empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Doctrine alignment', '⚠', '`portrait = None` — no entry, but the design_note explicitly frames this as a \"win-condition engine\" (passive path to Established-in-more-districts). That\'s a meaningfully doctrinal outcome, softer flag than DIR.MOD.6 but worth the same question: should recurring, strategically significant doctrine-aligned actions carry a portrait entry, or is routine/automatic execution enough to justify `None`?', 'Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Card type fit', '✓', 'ModReactCard/Directorate, real taxonomy (Territory/Add/PresenceToken, 04-n175).', 'Art 04 §6.1, §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Taxonomy fit', '✓', 'Confirmed as the Ring set\'s own STD.MOD.98 precedent (04-n175 note) — verified on re-check, not just cited.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Balance', '⚠', 'No restriction, no cost, fires on any opponent\'s structure placement anywhere on the board — the strongest, least-gated card reviewed in this set so far. \"Win-condition engine\" per its own design_note is not an exaggeration. Flag for real balance attention (not just the generic 04-n178 cost question) — consider whether a restriction (e.g., Established-gate, like the enforcement family) or a ring/frequency limiter belongs here.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Effect duration', '✓', 'Immediate.', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Persistence', '⚠ (deferred)', 'Same open schema question as the rest of the set.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Trigger validity', '✓', '`structure_block.placed(faction=opponent)` — confirmed vocabulary, correctly opponent-scoped (no self-fire ambiguity, unlike DIR.MOD.1/3).', 'Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Portrait validity', '⚠', 'Same question as Doctrine alignment row above.', 'Art 04 §6.2 P11', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Supported by zones', '✓', '`target_district=trigger.district` — correct; also naturally excludes Chorus Node since no structures are ever placed there (GR 8.1a), so no special-case needed.', 'Art 01 §6–7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Supported by components', '✓', 'Standard chip-placement mechanism; GR 8.1\'s 6-chip cap is a generally enforced constraint across all presence-adding cards, not a gap specific to this one.', 'Art 02 §6–8', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Supported by game procedure', '✓', 'Reuses existing structure-placement event and chip-placement mechanism; no new procedure needed.', 'Art 03; GR 6.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Data schema validation', '⚠ (deferred)', 'Scaffolded (04-n177) — placeholders only.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Card narrative', '⚠', '`narrative` field empty; Card Story above is new this pass.', 'Art 04 §5 Card Story', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Outcome determinacy', '✓', 'Automatic, single success branch.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Resource cost positioning', '⚠', '`cost=None` — same 04-n178 gate as the rest of the set, but this card is the strongest candidate for actually needing a real (non-Floor-Act) cost given the Balance flag above.', 'Art 00a §9.2; PM05 04-n178', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Trigger frequency (ModReactCard)', '⚠', 'Structure placement is a common, recurring board event across all 4 other factions — likely the highest-frequency trigger reviewed in this set. Ties directly into the Balance flag.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Firing window (ModReactCard)', '✓', 'No other Directorate card in this set shares this trigger (cross-deck collision against Ring/other-faction content not checked — out of this batch\'s scope, matching the Ring template\'s own precedent).', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Automatic vs. d100 (ModReactCard)', '✓', 'Bounded, binary claim — no execution-quality dimension.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as the rest of the set: 2 copies → 2 chips per opponent structure placement? Undocumented, and more balance-relevant here than elsewhere given the Balance flag.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.7', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct; fires table-wide by design.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Action fit', '✓', 'Bureaucratic taxation on public acts in Directorate-administered territory is a clean, grounded expression of institutional oversight.', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Voice fit', '✓', 'Tagline reads correctly. `narrative` field empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Doctrine alignment', '✓', '`portrait = None` — routine bureaucratic action, not a strong doctrinal statement; empty is justified here (unlike DIR.MOD.6/7\'s stronger doctrinal actions).', 'Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Card type fit', '✓', 'ModReactCard/Directorate, real taxonomy (Submission/Remove/NativeResource, 04-n175).', 'Art 04 §6.1, §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Taxonomy fit', '✓', 'Impounds a resource off an already-submitted PA — Submission (interferes with submission), not plain Economy; matrix confirms Submission×Remove valid.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Balance', '✓', 'Costs 2 resources (Mandate+Capital) to remove 1 from an opponent\'s submitted PA — roughly symmetric, not an obvious exploit.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Effect duration', '✓', 'Immediate.', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Persistence', '⚠ (deferred)', 'Same open schema question as the rest of the set.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Trigger validity', '✓', 'Event itself (`public_act.placed_on_frg`) is confirmed vocabulary; `target_district=district.where(...)` now confirmed §6.3 vocabulary (schema_cleanup_log #9, PM05 04-n200), harmonized to the receiver form used elsewhere.', 'Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Portrait validity', '✓', 'Empty `{}` justified per Doctrine alignment row.', 'Art 04 §6.2 P11', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Supported by zones', '✓', 'Condition is district-scoped via the Directorate-Established filter; consistent with existing zone model.', 'Art 01 §6–7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Supported by components', '✓', 'Resource-token removal off a submitted card reuses the standard payment/submission mechanism; correctly routes to Reservoir, not Directorate income — checked against GR 9.1/§4.16, not a violation.', 'Art 02 §6–8; GR 9.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Reuses the existing §9.2 FRG-placement event and Beat 4 payment/shortfall procedure (P20) — no new ARBITER behavior.', 'Art 03; GR 6.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Data schema validation', '⚠ (deferred)', 'Scaffolded (04-n177) — placeholders only.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Card narrative', '⚠', '`narrative` field empty; Card Story above is new this pass.', 'Art 04 §5 Card Story', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Outcome determinacy', '✓', 'Automatic, single success branch.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Resource cost positioning', '✓', 'Real cost specified (Mandate+Capital), not gated on 04-n178 the way the cost-less cards are; reasoning (Capital mobilizes seizure teams, Mandate authorizes it) is sound.', 'Art 00a §9.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Trigger frequency (ModReactCard)', '✓ (best-effort)', 'Fires whenever any PA targets a Directorate-Established district — moderate, bounded by how much territory Directorate holds.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Firing window (ModReactCard)', '✓', 'No other Directorate card shares this trigger.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Automatic vs. d100 (ModReactCard)', '✓', 'Flat impoundment, no execution-quality dimension.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as the rest of the set: 2 copies → 2 resources impounded per qualifying PA? Undocumented.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.8', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct; gated by Directorate\'s Established territory, not a fixed ring.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Action fit', '✓', 'Opportunistic institutional sanction off a rival\'s public misstep is a grounded Directorate beat, distinct from the enforcement family\'s territorial focus.', 'Art 00 §7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Voice fit', '✓', 'Tagline (\"the public already turned on them\") lands the doctrine. `narrative` field empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Doctrine alignment', '✓', '`{Directorate: submitter=+1}` — submitter-bounded, correctly expresses doctrine on play.', 'Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Card type fit', '✓', 'ModReactCard/Directorate, `persistence=Permanent` — correctly typed for the card-as-condition pattern.', 'Art 04 §6.1, §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Taxonomy fit', '✓', 'Submission/Block/PublicAct — dominant identity is blocking PA submission, the +1 PS is secondary. Matrix confirms Submission×Block valid.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Balance', '⚠', 'Cannot close: severity depends directly on the 4.8c question below (a total PA lock is far more severe than a Floor-Act-exempted one).', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Effect duration', '✓', '`persistence=Permanent` correctly typed for an explicit-clearing-condition card.', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Persistence', '✓', 'Clearing event carries its own field, `persistence_clearing_trigger`, distinct from the continuous-predicate `persistence_condition` (`None`, correctly).', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Trigger validity', '✓', '`standing_marker.decreased(faction=Any, except=Directorate)` — confirmed vocabulary; explicit `except=Directorate` since firing against Directorate itself would be self-harmful, not a no-op.', 'Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Portrait validity', '✓', '`{Directorate: submitter=+1}` justified — opening a sanction is a deliberate, doctrinally-loaded choice (distinct from the Standard-card portrait-absence convention).', 'Art 04 §6.2 P11', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Supported by zones', '✓', '`target_district=None` — correct; this isn\'t a district-scoped effect.', 'Art 01 §6–7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Supported by components', '✓', 'Intel Token consumption and standing-marker reaction both reuse existing components; no new component needed.', 'Art 02 §6–8', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Supported by game procedure', '⚠', '**Real flag (not resolved here):** `persistence_effect = PublicAct(submitter=trigger.faction).blocked_at(phase_b)` blocks *all* PA submission from the sanctioned faction. Design Pillar 4.8c: the Floor Act is always available and cannot be blocked. A total lock appears to conflict with this HARD rule — needs a design decision (implicit Floor Act exemption vs. narrowing this card\'s scope) before Issues Resolved can close.', 'Art 03; GR 6.1; Design Pillar 4.8c', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Data schema validation', '⚠', 'Scaffolding placeholders added (04-n177), still open. `cost = IntelToken(about=trigger.faction, status=[Fresh, Stale]) * 1` is confirmed §6.3 vocabulary.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Card narrative', '⚠', '`narrative` field empty; Card Story above is new this pass.', 'Art 04 §5 Card Story', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Outcome determinacy', '✓', 'Automatic, single success branch.', 'Art 04 §5 P27', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Resource cost positioning', '✓', 'Real cost specified (Intel Token, not the 04-n178 Floor-Act gate) — cost type is confirmed §6.3 vocabulary.', 'Art 00a §9.2; Art 04 §6.3', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Trigger frequency (ModReactCard)', '⚠', 'PS drift alone (above-13 Quarter-end decay) means `standing_marker.decreased` fires regularly for any faction sitting above Neutral — potentially high-frequency, gated only by holding a matching Intel token. Ties directly into the Balance flag.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Firing window (ModReactCard)', '✓', 'No other Directorate card shares this trigger.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Automatic vs. d100 (ModReactCard)', '✓', 'Binary sanction-opening, no execution-quality dimension.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Stack behavior (ModReactCard)', '⚠', 'Since this creates a Permanent standing condition (not fire-and-consume), does a 2nd copy targeting the same faction do anything, or targeting a different faction simultaneously? More consequential here than the set\'s generic stack question given the severity of the effect.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.9', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct; not ring-scoped.', '', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Action fit', '✓', 'Enforcement personnel thrown into a live contest is the textbook literal expression of §5a\'s \"military assets\" doctrine.', 'Art 00 §7; Art 04 §5a', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Voice fit', '✓', 'Scoped to `narrative`/`arbiter_note` only (`perspectives`/`design_note` schema-locked None for ModBattleCard); institutional-enforcement register throughout.', 'Art 00 §9', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Doctrine alignment', '✓', 'Boost directly expresses §5a\'s literal-force doctrine; `doctrine_mod`/`target_faction` correctly None — the target lives in `ModBattleExpr.target`, not a Card-level field.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Card type fit', '✓', 'ModBattleCard/FactionSpecific correct; fills the Asset-category naming slot in the locked 2 Boost/2 Hinder pattern.', 'Art 04 §6.1, §11.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Taxonomy fit', 'N/A', 'Schema-locked None — contest itself is the taxonomy-bearing act, not the modifier (§11.1).', 'Art 04 §6.2, §11.1', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Balance', '✓', 'Weak Boost tier per the locked pattern; no cost step exists for this subclass (Art 03 §10.1.2); magnitude/value_rating playtest-flagged (04-n94), not re-litigated here.', 'PM05 04-n94', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Effect duration', 'N/A', 'Immediate-resolution — fires at commit, discarded at §10.1.4 cleanup, no multi-Quarter persistence.', 'Art 04 §5 P19', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Persistence', 'N/A', 'Schema-locked None.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Trigger validity', 'N/A', 'Schema-locked None — fires at Battlefield Strength commit (§10.1.2 Step 1.2.2), not a trigger condition.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Portrait validity', '✓', '`portrait=None` is correct and permanent — ModBattleCard carries no portrait value (locked whole-subclass convention). Effect is a mechanical Boost/Hinder with doctrinal alignment already captured via Doctrine alignment/narrative; no independent per-faction scoring needed.', 'Art 04 §6.1–§6.2', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Supported by zones', '✓', 'No `target_district` (schema-locked None); `ring_constraint=None` correct for a faction-deck card (only Ring-modifier-deck cards carry a set ring_constraint, 04-n161).', 'Art 01 §6–§7', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Supported by components', '✓', 'No new components invoked; Battlefield Modifier Card mechanic already established.', 'Art 02', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Supported by game procedure', '✓', 'Prior `arbiter_note` was found fully redundant with the card\'s own fields and/or an already-existing, verified Art 03 procedure (S154 follow-up) and removed — card now carries no note and no comment, genuinely supported.', 'Art 03 §10.1.2, §10.1.4', '04___Card_System___Part4c_Directorate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Data schema validation', '✓', '`ps_framing`/`boost`/`resolution_type` added as explicit None placeholders (04-n177 scaffolding, not previously applied to this subclass).', 'Art 04 §6.1–§6.3; 04-n177', '04___Card_System___Part4c_Directorate.md');
