INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('DIR.MOD.10', 'Outcome determinacy', 'N/A', 'Schema-locked None — no success/successcrit/fail/failcrit fields; effect is a printed deterministic value, not a resolution tier.', 'Art 04 §6.2', '04___Card_System___Part4c_Directorate.md');
