INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.PA.5', 'Trigger validity', '✓', 'No trigger field; Automatic doesn\'t require one', '—', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.PA.5', 'Portrait validity', '⚠', '`portrait = None` is present (not absent) but unjustified. See PM05 04-n218.', 'Art 04 §6.2', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.PA.5', 'Supported by zones', '✓', '`target_faction = faction.opponent` is present as a real Card field. Earlier \"no target_faction field declared\" claim was false — corrected.', 'Art 01 §6–§7', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.PA.5', 'Supported by components', '✓', 'Public Standing track, native resources — existing components', 'Art 02 §7–§8', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.PA.5', 'Supported by game procedure', '✓', 'Cost is paid entirely from Network\'s own resource pool (confirmed CostExpr rule) — the `faction.target.native` term only resolves which resource type is owed (the target\'s native type), not who pays it. Same \"prior economic embedding\" shape as GHO.CA.4: Network must already hold a unit of the target\'s native resource for this cost to be payable.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.PA.5', 'Data schema validation', '⚠', '`card_id` present (`card_id = \"NET.PA.5\"`), as are `outcome_type`/`ring_mod`/`doctrine_mod`/`trigger`/`resolution_type`/`persistence`/targeting fields/`restriction`/`boost`/`successcrit`/`fail`/`failcrit`/`arbiter_note` — earlier \"missing entirely\" claim was false across the board (confirmed against audit tool: only `persistence_clearing_trigger`/`on_discard` genuinely absent). Real gap: **`success` is a bare prose string, not a structured MutationExpr** — see PM05 04-n218.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.PA.5', 'Card narrative', '⚠', 'Pending 04-n79; no Card Story block', 'Art 04 §5 P26', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.PA.5', 'Outcome determinacy', '⚠', '`successcrit`/`fail`/`failcrit` correctly `None` (not a false gap) — but `success` being prose, not code, can\'t be verified as a genuine deterministic MutationExpr against P27. See PM05 04-n218.', 'Art 04 §5 P27', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.PA.5', 'Resource cost positioning', '✓', 'Cross-resource (2 Exposure — Network\'s own native — + 1 unit of the target\'s native type), both paid from Network\'s own pool.', 'Art 00a §9.2', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.PA.6', 'Action fit', '✓', 'Converting public goodwill (PS) into hard resources is a distinctive, doctrinally-grounded Network economy mechanism', 'Art 00 §7', '04___Card_System___Part4d_Network.md');
