INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Action fit', '✓', 'Opportunistic chip placement on any publicly-observable PA board-state change fits Network\'s reach-first doctrine.', 'Art 00 §7', '04___Card_System___Part4d_Network.md');
