INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Doctrine alignment', '✓', 'No prior presence required — doctrinal reach-first, matches Network\'s \"no one gets to decide this in the dark\" identity.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4d_Network.md');
