INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Taxonomy fit', '✓', 'Territory/Add/PresenceToken is valid: Territory×Add confirmed in the matrix. ModReactCard is not excluded from the taxonomy matrix (the exception among modifier subclasses).', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Balance', '⚠', 'Broad trigger (any PA board-state change table-wide) + no presence requirement is a real balance question, same shape as the \"least-gated\" cards DIR.MOD.7/GUI.MOD.2/8.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Effect duration', '✓', 'Immediate — chip placed at the Beat 4 trigger point.', 'Art 04 §5 P19', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Persistence', '✓', 'Explicitly declared (`persistence=Immediate`).', 'Art 04 §6.2', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Trigger validity', '✓', '`board_state.changed(component=[presence_chip, structure_block], change=Any, cause=public_act, faction=Any)` — confirmed §6.3 vocabulary. `cause=public_act` preserves the original PA-only gate.', 'Art 04 §6.3', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Portrait validity', '✓', 'Submitter-bounded, correctly structured.', 'Art 04 §6.2 P11', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Supported by zones', '✓', '`target_district` fixed by trigger, not a free choice.', 'Art 01 §6–7', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Supported by components', '✓', 'Chip placement and Exposure cost both standard.', 'Art 02 §6–8', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Beat 4 React, reuses existing Art 03 §18 React rules.', 'Art 03 §18', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Data schema validation', '✓', '`persistence`, `outcome_type`, and targeting fields are all explicitly declared; trigger now uses confirmed `board_state.changed(...)` vocabulary (`acting` checked and confirmed separately, was never a gap).', 'Art 04 §6.1–§6.3', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Card narrative', '✓', 'Card Story + `narrative` field both present and well-formed.', 'Art 04 §5 P26', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Outcome determinacy', '✓', 'Genuine two-branch outcome via a real d100 roll (not the invalid `Prediction` pattern GHO.MOD.1 used) — success/successcrit/fail/failcrit all properly structured.', 'Art 04 §5 P27', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Resource cost positioning', '✓', 'Exposure×1, Network-native — no cross-resource question.', 'Art 00a §9.2', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Trigger frequency (ModReactCard)', '⚠', 'Any PA board-state change table-wide is a broad, likely-frequent trigger. Ties into the Balance flag.', '', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Firing window (ModReactCard)', '✓', 'No other Network card shares this exact trigger.', '', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Automatic vs. d100 (ModReactCard)', '✓', 'd100 is the right call here — this models a genuine insertion-attempt risk (crit/fail bands shift PS), unlike the flat Automatic effects seen elsewhere in the corpus.', '', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.1', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as the rest of the corpus: 2 copies → 2 independent rolls per qualifying PA? Undocumented.', '', '04___Card_System___Part4d_Network.md');
