INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.3', 'Taxonomy fit', '✓', 'Standing×Shift valid per the matrix.', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4d_Network.md');
