INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.12', 'Supported by components', '✓', 'Target Profile (face-down mechanism) — existing component.', 'Art 02 §6, §11', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.12', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: Reacts at Art 03 §9.2.0; face-down Target Profile mechanism and Beat 4 resolution both pre-existing procedure.', 'Art 03 §9.2.0; Art 03 §14', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.12', 'Data schema validation', '⚠', 'Trigger/success expressed in current Expr syntax (04-n174). `arbiter.reveal(...)` has no confirmed MutationExpr vocabulary — same open gap as the rest of the corpus.', 'Art 04 §6.1–§6.3; PM05 04-n174', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.12', 'Card narrative', '✓', 'Card Story present; narrative reads clean.', 'Art 04 §5 P26', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.12', 'Outcome determinacy', '✓', '`Automatic` — deterministic, no dice.', 'Art 04 §5 P27', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.12', 'Resource cost positioning', '✓', '`Exposure(1)` — light cost for a purely informational counter.', 'Art 00a §9.2', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.12', 'Trigger frequency (ModReactCard)', '⚠', 'Depends on how often opponents place PAs with face-down Target Profiles — best-effort, not independently verifiable here.', '', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.12', 'Firing window (ModReactCard)', '✓', 'Shares its trigger with GHO.MOD.11 (Manufactured Evidence) but the two effects don\'t overlap in resolution.', '', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.12', 'Automatic vs. d100 (ModReactCard)', '✓', 'Deterministic condition check, no dice — Automatic is correct.', '', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.12', 'Stack behavior (ModReactCard)', '⚠', 'Same open corpus-wide question: is a 2nd copy meaningful? Undocumented.', '', '04___Card_System___Part4d_Network.md');
