INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Action fit', '✓', 'Protecting Network\'s own high-stakes PA with a credentialed-immunity framing is a coherent, high-power doctrinal statement.', 'Art 00 §7', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Voice fit', '✓', 'Tagline (\"no one pulls a credentialed signal off the air\") lands the doctrine precisely.', 'Art 00 §6.7', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Doctrine alignment', '✓', 'Portrait submitter=+1 — correctly expresses doctrine on a deliberate, high-stakes play.', 'Art 04 §6.5', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Card type fit', '✓', 'ModReactCard/Network, real taxonomy (Submission/Protect/PublicAct, 04-n175).', 'Art 04 §6.1, §6.2', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Taxonomy fit', '✓', 'Submission×Protect valid per the matrix; Protect correctly assigns to the layer of the protected target (Construction Logic rule 3).', 'Art 04b §4; ref_taxonomy.md §5.1', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Balance', '⚠', '\"Ceiling-power\" per its own design_note — total immunity from targeting is a strong, precedent-setting effect. Real cost (3 resources, 2 foreign) partially offsets it, but the effective cost depends on whether Network can reliably hold Findings/Mandate — see Resource cost positioning.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Effect duration', '✓', '`persistence=Seasonal`, bounded by `persistence_condition` to exactly the protected PA\'s own lifetime — clears the instant it resolves, not at Quarter end.', 'Art 04 §5 P19', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Persistence', '✓', '`persistence=Seasonal`, `persistence_condition = not trigger.card.resolved`, `persistence_effect = arbiter.protect(trigger.card, from=targeting)`.', 'Art 04 §6.2', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Trigger validity', '✓', '`public_act.placed_on_frg(faction=Network)` — confirmed vocabulary, self-scoped, no ambiguity.', 'Art 04 §6.3', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Portrait validity', '✓', 'Submitter-bounded, correctly structured.', 'Art 04 §6.2 P11', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Supported by zones', '✓', '`target_district=None` — correct; this isn\'t a territory effect.', 'Art 01 §6–7', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Supported by components', '✓', 'No new component needed — protection is a rules-state condition on an existing PA.', 'Art 02 §6–8', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Supported by game procedure', '⚠', 'Card carries a real `arbiter_note`/inline comment — per S154 rule, a clean card should have zero of either; presence means Art 03 doesn\'t yet cover this mechanic standalone (new procedure and/or card redesign needed), not yet ✓. Prior note: `arbiter_note` gives a clear procedural description (record protected PA, block targeting until it resolves, clear on resolution), matching the structured `persistence_effect` now backing it.', 'Art 03; GR 6.1', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Data schema validation', '✓', '`persistence_effect = arbiter.protect(trigger.card, from=targeting)` — valid confirmed MutationExpr. `success=None`; the card\'s one-time trigger action is establishing the Standing Condition itself.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Card narrative', '✓', 'Card Story above is concrete; `narrative` field itself is still `None`.', 'Art 04 §5 Card Story', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Outcome determinacy', '✓', 'Automatic, single effect, no branching.', 'Art 04 §5 P27', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Resource cost positioning', '⚠', 'Real cost specified, but requires TWO foreign resource types (Findings/Ghost, Mandate/Directorate) alongside Network\'s own Exposure — the sharpest cross-resource-holding instance in the set (sharper than GHO.MOD.7\'s one-of-three). Design_note frames this as intentional (\"requires trade relationships with Ghost and Directorate\") — a real design choice, but one that makes this card\'s actual accessibility highly dependent on diplomacy.', 'Art 00a §9.2', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Trigger frequency (ModReactCard)', '✓ (best-effort)', 'Gated on Network placing a PA — moderate, self-limiting frequency.', '', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Firing window (ModReactCard)', '✓', 'No other Network card shares this trigger.', '', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Automatic vs. d100 (ModReactCard)', '✓', 'Deterministic protection, no execution-quality dimension.', '', '04___Card_System___Part4d_Network.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('NET.MOD.13', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as the rest of the corpus.', '', '04___Card_System___Part4d_Network.md');
