INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.4', 'Data schema validation', '⚠', 'Verified against `--dump-d`: only boilerplate `persistence_clearing_trigger`/`on_discard` genuinely absent — every field the prior note claimed \"missing entirely\" (`outcome_type`, `ring_mod`/`doctrine_mod`/`trigger`/`resolution_type`, `persistence`, targeting fields, `restriction`, `boost`, `successcrit`/`fail`/`failcrit`, `card_id`, `arbiter_note`) is actually declared, just `=None #scaffolded`. The one real, confirmed gap: `success` is a bare prose string, not a structured MutationExpr. Logged, PM05 04-n220.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.4', 'Card narrative', '⚠', 'Pending 04-n79; no Card Story block', 'Art 04 §5 P26', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.4', 'Outcome determinacy', '✓', '`Automatic`; single path (`success` only, `successcrit`/`fail`/`failcrit` all `None` by design) — no `game.choose_one()`. Determinacy itself is fine; the content of that one path isn\'t structured code (see Data schema validation).', 'Art 04 §5 P27', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.4', 'Resource cost positioning', '✓', 'Mono-resource (Capital × 2), correctly typed.', 'Art 00a §9.2', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Action fit', '✓', 'Capital-toll extortion on district development is grounded in Syndicate\'s leverage doctrine', 'Art 00 §7', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Voice fit', '⚠', '`narrative`/`perspectives` fields are present but both `None` — no voice content written, not a field-absence gap. Logged, PM05 04-n220.', 'Art 00 §7', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Doctrine alignment', '✓', 'On-doctrine — Capital positioned as a toll on others\' physical expansion', 'Art 00 §7', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Card type fit', '✓', 'PublicAct / FactionSpecific (Syndicate)', 'Art 04 §6.2', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Taxonomy fit', '✓', 'Territory / Remove / StructureBlock — matches `card_status` DB directly', 'Art 04b §4', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Balance', '⚠', 'Cost set, but the standing toll\'s actual power (removal threat on any placement) can\'t be assessed without a structured, bounded effect', 'Art 02 §6–§7', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Effect duration', '✓', '`persistence = Seasonal` — lasts through the remainder of the Quarter it\'s played in, matching the schema\'s defined Seasonal window exactly. Playing this in Month 3 yields no benefit (no remaining Months left for the toll to apply) — an intentional early-play tradeoff, not a defect.', 'Art 04 §5 P19', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Persistence', '✓', 'Seasonal — see Effect duration above', 'Art 04 §6', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Trigger validity', '⚠', 'The described trigger (\"whenever a Structure Block or Presence Token is placed here\") maps toward confirmed TriggerExpr vocabulary (`structure_block.placed`/`presence_chip.placed`) but isn\'t expressed as one — prose inside `success`, same Card-as-Condition gap as GUI.PA.3/8 and DIR.PA.7', 'Art 04 §6.3', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Portrait validity', '⚠', '`portrait = None` — present but unjustified-empty; the toll mechanism has no portrait entry decided yet. Logged, PM05 04-n220.', 'Art 04 §6.2', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Supported by zones', '✓', '`target_district = district.named` — present and populated (prior note claiming it wasn\'t declared was wrong).', 'Art 01 §6–§7', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Supported by components', '✓', 'StructureBlock, PresenceToken, Capital — existing components', 'Art 02 §6–§8', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Supported by game procedure', '⚠', 'The pay-or-lose-asset reactive mechanism has no structured procedural home — same gap as Trigger validity above', 'Art 03 §9', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Data schema validation', '⚠', 'Verified against `--dump-d`: only boilerplate `persistence_clearing_trigger`/`on_discard` genuinely absent — every field the prior note claimed \"missing entirely\" (`outcome_type`, `ring_mod`/`doctrine_mod`/`trigger`/`resolution_type`, all four targeting fields, `restriction`, `boost`, `successcrit`/`fail`/`failcrit`, `card_id`, `arbiter_note`) is actually declared, most `=None #scaffolded`, and `target_district` carries a real value (`district.named`). The one real, confirmed gap: `success` is a bare prose string describing what should be a `persistence_effect`. Logged, PM05 04-n220.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Card narrative', '⚠', 'Pending 04-n79; no Card Story block', 'Art 04 §5 P26', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Outcome determinacy', '✓', '`Automatic`; single path (`success` only, `successcrit`/`fail`/`failcrit` all `None` by design) — no `game.choose_one()`. Determinacy itself is fine; the content of that one path isn\'t structured code (see Data schema validation).', 'Art 04 §5 P27', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.PA.5', 'Resource cost positioning', '✓', 'Cross-resource (Capital + Mandate), correctly typed.', 'Art 00a §9.2', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Action fit', '✓', 'Post-activation Accord sabotage — strikes a clause the moment the deal takes effect. Fits Syndicate\'s leverage-based interference doctrine.', 'Art 00 §7', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Voice fit', '⚠', 'Perspectives TBD — deferred to modifier card voice pass (D-04-08); `narrative` line present.', 'Art 00 §9', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Doctrine alignment', '✓', 'Corrupting/removing Accord terms via leverage (keyed IntelToken) is squarely Syndicate\'s \"we have something on everyone\" doctrine — matches sibling cards SYN.MOD.11 and SYN.CA.11.', 'Art 00 §7; Art 04 §6.5', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Card type fit', '✓', 'Issued `ModReactCard` — ARBITER-delivered, not deck-drawn.', 'Art 04 §6.1, §11.1', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Taxonomy fit', '⚠', 'AccordAgreement is confirmed registered (Redline\'s precedent) and Remove is a confirmed verb, but Remove-vs-Corrupt is a genuine judgment call, not a settled fit — Corrupt\'s actual definition (\"a physically written value is altered\") arguably matches \"void a clause\" better than Remove\'s (\"component exits active play\"), since the AccordAgreement itself stays in play. Kept as Remove for now; flagged for re-check, same as SYN.MOD.11\'s own self-flagged assignment.', 'ref_taxonomy.md §5.2', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Balance', '✓', '`cost = Findings * 1 + IntelToken(about=declared_party)` — lighter than Signature on File\'s 4-resource stack, appropriate since removing one clause is a smaller violation than forcing whole-Accord acceptance. New cost combination, playtest-flagged like the rest of the corpus\'s numeric values (04-n94 pattern), not re-litigated further.', 'Art 02 §6–§7', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Effect duration', '✓', 'Immediate — the strike itself resolves instantly at trigger; the missing clause\'s absence persists for the remainder of the Accord\'s term, same durability pattern as Redline\'s in-place alteration.', 'Art 04 §5 P19', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Persistence', '⚠', '`persistence` field open corpus-wide question, not card-specific.', 'Art 04 §6.2', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Trigger validity', '⚠', '`accord.activated` is a brand-new trigger form, unconfirmed against §6.3 TriggerExpr vocabulary — same open category as Overture\'s `public_act.resolved` and SYN.MOD.11\'s `accord.tabled`.', 'Art 04 §6.3; PM05 04-n158', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Portrait validity', '✓', '`{Syndicate: submitter=+1}` (corrected from `flat=+1`, schema_cleanup_log #7 — Syndicate is this card\'s own submitter) — same structure and magnitude as SYN.CA.11 Redline\'s comparable Accord-manipulation play.', 'Art 04 §6.2', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Supported by zones', '✓', 'No district reference — correct, not a territory effect.', 'Art 01 §6–§7', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Supported by components', '✓', 'AccordForm, IntelToken — existing components; no new components needed.', 'Art 02 §6, §11; Art 06 §9.2', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Supported by game procedure', '⚠', 'Art 06 §9.10 defines Term removal at the rules level, but no Art 03 procedural pass yet describes exactly when in the sequence an Issued ModReactCard reacts to \"Accord activation\" — same category of gap as Overture\'s own flagged Art 07 subroutine pending item.', 'Art 06 §9.10; PM05 04-n158', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Data schema validation', '⚠', 'Brand-new card (no prior `Card()` definition existed). `target_object.alter(type=TermRemoval, ...)` parallels Redline\'s `type=Terms` but `TermRemoval` has no formal AlterType enum backing it — same ungoverned-MutationExpr gap as the rest of the corpus. `generating_card=None` flagged as a separate, still-open item (not a blocker for this pass). Scaffolding fields added (04-n177).', 'Art 04 §6.1–§6.3; PM05 04-n158', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Card narrative', '✓', 'Card Story and `narrative` line present (card previously had no content at all).', 'Art 04 §5 P26', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Outcome determinacy', '✓', '`Automatic` — deterministic leverage check (does Syndicate hold the right keyed IntelToken), no dice.', 'Art 04 §5 P27', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Resource cost positioning', '✓', '`Findings * 1 + IntelToken(about=declared_party)` — mirrors Signature on File\'s leverage-cost pattern at a lighter tier appropriate to the smaller violation.', 'Art 00a §9.2', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Trigger frequency (ModReactCard)', '⚠', 'Depends on Accord activation frequency plus Syndicate holding the right keyed IntelToken at the right moment — a fairly narrow combined condition; best-effort, not independently verifiable here.', '', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Firing window (ModReactCard)', '✓', 'No other card shares the `accord.activated` trigger.', '', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Automatic vs. d100 (ModReactCard)', '✓', 'Deterministic leverage check, no dice — Automatic is correct.', '', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Stack behavior (ModReactCard)', '⚠', 'Same open corpus-wide question: is a 2nd copy meaningful? Undocumented.', '', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.1', 'Ring constraint (ModReactCard)', '✓ (N/A)', '`ring_constraint=None` — not a district/ring-scoped effect.', '', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.2', 'Action fit', '✓', '\"Economic positioning without needing to be invited\" is a clean, doctrinally central Syndicate beat.', 'Art 00 §7', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.2', 'Voice fit', '✓', 'Tagline reads correctly. `narrative` field empty — see Card narrative row.', 'Art 00 §6.7', '04___Card_System___Part4e_Syndicate.md');
