INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.2', 'Card type fit', '✓', 'ModReactCard/Syndicate, real taxonomy (Economy/Add/NativeResource, 04-n175).', 'Art 04 §6.1, §6.2', '04___Card_System___Part4e_Syndicate.md');
