INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Action fit', '✓', 'Forcing a binding Accord through leverage rather than negotiation is the sharpest possible expression of Syndicate\'s \"control comes from positioning early\" doctrine.', 'Art 00 §7', '04___Card_System___Part4e_Syndicate.md');
