INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Balance', '✓', 'Four-resource cost (2 Capital + Findings + Mandate + a keyed Intel Token) for forcing a binding Accord is appropriately \"ceiling-power\" per its own framing — the most expensive Syndicate card reviewed this session.', 'Art 02 §6–7; Art 04 §6.5', '04___Card_System___Part4e_Syndicate.md');
