INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Persistence', '⚠ (deferred)', 'Not explicitly declared as a field — same open schema question as most of the corpus.', 'Art 04 §6.2', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Trigger validity', '⚠', '**Genuinely new, not just unreconciled:** `accord.tabled` is a pre-signature-stage event with no confirmed §6.3 form at all (confirmed vocabulary only covers post-formation Accord events — placed/corrupted/removed). The card\'s own text already flags this needs Art 06 timing confirmation.', 'Art 04 §6.3', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Portrait validity', '✓', '`submitter=+2` (corrected from `flat=+2`, schema_cleanup_log #7 — Syndicate is this card\'s own submitter). Magnitude (+2, vs. the more common +1) is self-flagged for confirmation — scale seems proportionate to the card\'s \"ceiling-power\" framing, but not independently re-derivable without a numeric Portrait-magnitude standard to check against.', 'Art 04 §6.2 P11', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Supported by zones', '✓', '`target_district=None` — correct; Accords have no district dimension.', 'Art 01 §6–7', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Supported by components', '✓', 'Intel Token consumption and Accord-form marking both reuse existing components.', 'Art 02 §6–8', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Supported by game procedure', '⚠', 'Depends on the unconfirmed `accord.tabled` trigger stage — the underlying Art 06 procedure for a \"tabled but unsigned\" Accord state isn\'t yet formally described.', 'Art 03; GR 6.1', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Data schema validation', '⚠', 'Real MutationExpr (`arbiter.mark_acceptance`) — ahead of SYN.MOD.6/8\'s string-literal gap. Cost includes an Intel Token — now confirmed §6.3 vocabulary (schema_cleanup_log #10). Scaffolding added for `resolution_type`/`boost`/`ps_framing`.', 'Art 04 §6.1–§6.3', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Card narrative', '⚠', '`narrative` field empty; Card Story above is new this pass.', 'Art 04 §5 Card Story', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Outcome determinacy', '✓', 'Automatic, single success branch.', 'Art 04 §5 P27', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Resource cost positioning', '✓', 'Cost is real and substantial; one of the four components (Intel Token) is now confirmed §6.3 vocabulary (schema_cleanup_log #10).', 'Art 00a §9.2; Art 04 §6.3', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Trigger frequency (ModReactCard)', '✓', 'Gated on holding a keyed Intel Token on the specific party — inherently rare, matching the \"ceiling-power\" framing.', '', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Firing window (ModReactCard)', '✓', 'No other Syndicate card shares this trigger.', '', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Automatic vs. d100 (ModReactCard)', '✓', 'Deterministic forgery, no execution-quality dimension.', '', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Stack behavior (ModReactCard)', '⚠', 'Same open question as the rest of the corpus.', '', '04___Card_System___Part4e_Syndicate.md');
INSERT INTO card_checklist (card_id, category, verdict, note, artifact_ref, source_file) VALUES ('SYN.MOD.11', 'Ring constraint (ModReactCard)', '✓', '`ring_constraint=None` — correct; not ring-scoped.', '', '04___Card_System___Part4e_Syndicate.md');
